observatory.script:
'use strict';
const $ = (s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const escapeHTML = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const families=['Registry','Logic','Safeguard','Telemetry','Covenant','Restoration'];
const colors={Registry:'#a3edcb',Logic:'#eac386',Safeguard:'#8bacde',Telemetry:'#75ced1',Covenant:'#b7a1d5',Restoration:'#dc927c'};
let state=null,activeView='field',selected=null,definitionMode='live',source=null,events=[],lastPulse=0,points=[],frame=0,dirty=true,modelState=null;
let reduced=localStorage.getItem('postscarcity-reduced')==='true'||matchMedia('(prefers-reduced-motion: reduce)').matches;
const titleMap={field:'Living field',chiral:'Chiral generator',models:'Model conversations',modules:'Module library',neural:'Neural weights',definitions:'Definition stream',processes:'Process bus',settings:'Settings',work:'Work board',sources:'Website & text',commands:'System commands',screen:'App & tab input'};
async function api(path,body){const response=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error||'The runtime could not complete this request');return data;}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function guarded(fn){return async event=>{try{await fn(event)}catch(error){toast(error.message)}};}
function number(value,digits=0){return Number(value||0).toLocaleString(undefined,{minimumFractionDigits:digits,maximumFractionDigits:digits});}
function shortTime(value){return value?new Date(value).toLocaleTimeString([], {hour12:false}):'Waiting';}
function setConnection(connected){$('#connection').textContent=connected?'FIELD CONNECTED':'RECONNECTING';$('#connection').classList.toggle('offline',!connected);$('#rail-status').textContent=connected?'Runtime connected':'Waiting for runtime';}
function showView(view){if(!titleMap[view])view='field';activeView=view;$$('.view').forEach(el=>el.classList.toggle('active',el.id===view));$$('nav [data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#breadcrumb').textContent=titleMap[view];history.replaceState(null,'','#'+view);renderView();if(view==='settings')fillSettings();if(view==='models')refreshModels();if(['models','work','sources'].includes(view))window.refreshExtensions?.();}
$$('[data-view]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.view)));
$('.brand').addEventListener('click',event=>{event.preventDefault();showView('field')});

async function bootstrap(){if(document.readyState==='loading')await new Promise(resolve=>document.addEventListener('DOMContentLoaded',resolve,{once:true}));state=await api('/api/state');events=state.events||[];$('#module-count').textContent=state.modules.length;$('.field-panel .tag').textContent=state.modules.length+' NODES';$('#prayer').textContent=state.chiral.prayer;$('#seed-pattern').textContent=state.chiral.pattern;fillSettings();buildFamilies();buildModelPanels();window.setupModelVoice?.();syncSliders();showView(location.hash.slice(1)||'field');connectStream();renderAll();}
function connectStream(){if(source)source.close();source=new EventSource('/api/events');source.onopen=()=>{setConnection(true);lastPulse=performance.now();};source.onerror=()=>setConnection(false);source.onmessage=event=>{let msg;try{msg=JSON.parse(event.data)}catch{return}const d=msg.data;
  if(msg.type==='shared-modules'){for(const row of d.modules){const m=state.modules.find(m=>m.id===row.id);if(m)Object.assign(m,row);}state.shared_execution=d.execution;}
  else if(msg.type==='pulse'){state.carrier=d;lastPulse=performance.now();}
  else if(msg.type==='chiral'){state.chiral={...state.chiral,...d};}
  else if(msg.type==='module'){const m=state.modules.find(m=>m.id===d.id);if(m)Object.assign(m,d);if(selected===d.id&&$('#module-dialog').open)refreshDetail(false);}
  else if(msg.type==='module-start'){const m=state.modules.find(m=>m.id===d.id);if(m)m.status='running';}
  else if(msg.type==='definition'){const index=state.definitions.findIndex(x=>x.term.toLowerCase()===d.term.toLowerCase());if(index>=0)state.definitions[index]=d;else state.definitions.push(d);}
  else if(msg.type==='processes'){state.processes=d.processes;state.host=d.host;state.clients=d.clients;}
  else if(msg.type==='neural'){state.neural=d;}
  else if(msg.type==='settings'){state.settings=d;syncSliders();}
  if(!['pulse','chiral','module-start','neural','processes','shared-modules'].includes(msg.type)){events.unshift(msg);events=events.slice(0,80);}
  dirty=true;
};}
function syncSliders(){if(!state)return;for(const [id,key] of [['carrier','carrier'],['chiral','chiral'],['prayer','prayer']]){const weight=state.neural.nodes.find(n=>n.id===key)?.weight??1;const input=$('#'+id+'-weight');if(document.activeElement!==input)input.value=weight;$('#'+id+'-weight-value').textContent=Number(input.value).toFixed(2);}}
function renderAll(){if(!state)return;const done=state.modules.filter(m=>m.runs>0).length,ready=state.definitions.filter(d=>d.status==='ready').length;
  $('#stat-modules').innerHTML=number(done)+'<small> / '+state.modules.length+'</small>';$('#stat-definitions').textContent=number(ready);$('#stat-def-caption').textContent=state.definitions.length+' source-derived concepts · auto refresh';$('#stat-processes').textContent=state.processes.length;if(state.shared_execution){const x=state.shared_execution;$('#stat-modules').closest('article').querySelector('p').textContent=`${x.complete} complete · ${x.awaiting_input} awaiting input · ${x.errors} errors`;}$('#stat-neural').textContent=number(state.carrier.neural_output??state.neural.output,3);$('#graph-output').textContent=number(state.carrier.neural_output??state.neural.output,3);
  const c=state.carrier;$('#measured').textContent=number(c.measured_hz,3)+' Hz';$('#pulse-count').textContent=number(c.pulses);$('#carrier-port').textContent=c.port;$('#subscribers').textContent=c.subscribers;$('#rail-port').textContent='LOCAL BUS · '+c.port;$('#bus-port').textContent='PORT '+c.port;$('#carrier-weight-value').textContent=Number($('#carrier-weight').value).toFixed(2);
  if(state.chiral){$('#generation').textContent='GENERATION '+number(state.chiral.generation);$('#chiral-drive').textContent=number(state.chiral.drive,3);$('#chiral-shift').textContent=(state.chiral.shift>0?'+':'')+state.chiral.shift+' / '+(-state.chiral.shift>0?'+':'')+(-state.chiral.shift);$('#chiral-ones').textContent=state.chiral.ones+' / '+state.chiral.cells;$('#chiral-toggle').textContent=state.settings.chiral_running?'Pause loop':'Resume loop';window.renderChiralText?.();}
  $('#learning-toggle').textContent=state.settings.learning?'Pause learning':'Resume learning';renderActivity();renderView();}
function renderView(){if(!state)return;if(activeView==='modules')renderModules();if(activeView==='definitions')renderDefinitions();if(activeView==='neural')renderNeural();if(activeView==='processes')renderProcesses();}
function stateText(m){if(m.status==='awaiting input')return 'AWAITING INPUT';if(m.status==='error')return'EXECUTION ERROR';if(m.status==='pending'||m.status==='queued')return m.status.toUpperCase();if(m.status==='running')return'RUNNING';return(m.trit!==null?'TRIT '+(m.trit>0?'+':'')+m.trit:m.gate!==null?'GATE '+(m.gate?'HOLD':'OPEN'):'COMPLETED');}
function renderModules(){const query=$('#module-search').value.toLowerCase(),family=$('#family-filter').value;const list=state.modules.filter(m=>(!family||m.family===family)&&(m.title+' '+m.description+' '+m.terms.join(' ')).toLowerCase().includes(query));$('#module-grid').innerHTML=list.length?list.map(m=>`<button class="panel module-card" data-module="${escapeHTML(m.id)}" data-family="${m.family}"><header><span>${m.family.toUpperCase()}</span><span class="state ${m.status==='error'?'error-tag':''}">${stateText(m)}</span></header><canvas data-mini="${m.family}" data-seed="${seed(m.id)}" aria-hidden="true"></canvas><h2>${escapeHTML(m.title)}</h2><small class="input-basis">${escapeHTML(m.input_basis||"Rule calculation")}</small><p>${escapeHTML(m.description)}</p><footer><span>${m.methods.length} methods · ${m.terms.length} concepts</span><span>${m.runs?'↻ '+m.runs+' passes':'Ready to run'} ↗</span></footer></button>`).join(''):'<p class="empty">No modules match this search.</p>';$$('[data-module]',$('#module-grid')).forEach(b=>b.addEventListener('click',()=>openModule(b.dataset.module)));}
function buildFamilies(){$('#family-grid').innerHTML=families.map(f=>`<button class="family-card" data-family="${f}"><canvas data-mini="${f}" data-seed="1" aria-hidden="true"></canvas><strong>${f}</strong><small>${state.modules.filter(m=>m.family===f).length} ↗</small></button>`).join('');$$('.family-card').forEach(b=>b.addEventListener('click',()=>{$('#family-filter').value=b.dataset.family;showView('modules')}));}
function renderActivity(){const recent=[...events].sort((a,b)=>b.seq-a.seq).slice(0,10);$('#activity').innerHTML=recent.map(e=>{const d=e.data;let text=e.type==='module'?`${d.id.replace('Engine','')} <b>${stateText(d)}</b>`:e.type==='definition'?`Definition · ${escapeHTML(d.term)} <b>${escapeHTML(d.status)}</b>`:e.type==='network'?escapeHTML(d.message):e.type==='model-response'?`${escapeHTML(d.provider)} response · ${d.characters} characters`:e.type==='process-event'?`Process ${d.pid} · ${escapeHTML(d.topic)}`:'Runtime settings updated';return`<div class="event"><time>${shortTime(e.time)}</time><span>${text}</span></div>`}).join('')||'<p class="empty">Listening for the first event…</p>';}
function renderNeural(){const n=state.neural;$('#neural-total').textContent=number(state.carrier.neural_output??n.output,3);$('#neural-nodes').textContent=n.nodes.length;$('#neural-edges').textContent=n.edge_count;if($('#weight-table').contains(document.activeElement))return;const query=$('#weight-search').value.toLowerCase(),kind=$('#weight-kind').value;const nodes=n.nodes.filter(n=>(!kind||n.kind===kind)&&n.label.toLowerCase().includes(query));$('#weight-table').innerHTML=nodes.map(n=>`<tr><td>${escapeHTML(n.label)}</td><td>${escapeHTML(n.kind)}</td><td>${Number(n.input).toFixed(3)}</td><td class="node-activation">${Number(n.activation).toFixed(3)}</td><td><div class="weight-control"><input type="range" min="-3" max="3" step="0.05" value="${n.weight}" data-weight="${escapeHTML(n.id)}" aria-label="Weight for ${escapeHTML(n.label)}"><output>${n.weight.toFixed(2)}</output></div></td></tr>`).join('');$$('[data-weight]').forEach(input=>{input.addEventListener('input',()=>input.nextElementSibling.textContent=Number(input.value).toFixed(2));input.addEventListener('change',guarded(async()=>{await api('/api/weight',{id:input.dataset.weight,weight:Number(input.value)});const node=state.neural.nodes.find(n=>n.id===input.dataset.weight);if(node)node.weight=Number(input.value);toast('Neural weight saved')}));});}
function renderDefinitions(){if(definitionMode==='calls'){window.renderCallDefinitions?.();return;}const query=$('#definition-search').value.toLowerCase();if(definitionMode==='original'){const items=state.modules.filter(m=>Object.keys(m.definitions).length&&(m.title+JSON.stringify(m.definitions)).toLowerCase().includes(query));$('#ingest-caption').textContent='Original registry entries read directly from the source files.';$('#definitions-grid').innerHTML=items.map(m=>`<article class="panel definition-card"><header><h2>${escapeHTML(m.title)}</h2><span class="tag">ORIGINAL</span></header><pre>${escapeHTML(JSON.stringify(m.definitions,null,2))}</pre><div class="module-chips"><button data-open-module="${escapeHTML(m.id)}">Open source module ↗</button></div></article>`).join('');}else{const ready=state.definitions.filter(d=>d.status==='ready').length;$('#ingest-caption').textContent=`${ready} of ${state.definitions.length} concepts retrieved · one request every ${state.settings.ingest_seconds}s · ${state.settings.ingestion?'automatic ingestion active':'ingestion paused'}`;const order={fetching:0,ready:1,retry:2,pending:3};const defs=state.definitions.filter(d=>(d.term+' '+(d.title||'')+' '+(d.text||'')).toLowerCase().includes(query)).sort((a,b)=>order[a.status]-order[b.status]||a.term.localeCompare(b.term));$('#definitions-grid').innerHTML=defs.map(d=>`<article class="panel definition-card"><header><h2>${escapeHTML(d.term)}</h2><span class="tag ${d.status==='ready'?'mint':''}">${escapeHTML(d.status.toUpperCase())}</span></header><p>${escapeHTML(d.text||d.error||'Queued from the original source. This definition will be fetched automatically.')}</p>${d.url?`<a href="${escapeHTML(d.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(d.title)} · ${escapeHTML(d.source)} ↗</a><small>Retrieved ${shortTime(d.retrieved)} · ${escapeHTML(d.license)}</small>`:''}<div class="module-chips">${d.modules.map(id=>`<button data-open-module="${escapeHTML(id)}">${escapeHTML(id.replace('Engine',''))}</button>`).join('')}</div></article>`).join('')||'<p class="empty">No matching definitions.</p>'; }$$('[data-open-module]',$('#definitions-grid')).forEach(b=>b.addEventListener('click',()=>openModule(b.dataset.openModule)));}
function renderProcesses(){$('#process-table').innerHTML=state.processes.map(p=>`<tr><td>${escapeHTML(p.scripts.join(' / ')||p.name)}<small>${escapeHTML(p.name)}</small></td><td>${p.pid}</td><td>${p.language}</td><td>${number(p.cpu,1)}%</td><td>${number(p.memory_mb,1)} MB</td><td class="mint">${escapeHTML(p.mode)}</td></tr>`).join('')||'<tr><td colspan="6">No visible Python or Java processes. Discovery continues every three seconds.</td></tr>';const messages=events.filter(e=>e.type==='process-event');$('#process-messages').innerHTML=messages.map(e=>`<div class="event"><time>${shortTime(e.time)}</time><span><b>PID ${e.data.pid} · ${escapeHTML(e.data.topic)}</b><br>${escapeHTML(JSON.stringify(e.data.payload))}</span></div>`).join('')||'<p class="muted">Listening for application events from connected adapters.</p>';}
function fillSettings(){if(!state)return;const form=$('#settings-form');for(const [key,value]of Object.entries(state.settings)){const input=form.elements.namedItem(key);if(!input)continue;if(input.type==='checkbox')input.checked=value;else input.value=value;}$('#reduce-motion').checked=reduced;}

$('#run-all').addEventListener('click',guarded(async()=>{const r=await api('/api/run',{id:'all'});toast(`${r.scheduled} modules queued`)}));
for(const [input,handler]of [['module-search',renderModules],['family-filter',renderModules],['weight-search',renderNeural],['weight-kind',renderNeural],['definition-search',renderDefinitions]])$('#'+input).addEventListener('input',handler);
$$('[data-definition-mode]').forEach(b=>b.addEventListener('click',()=>{definitionMode=b.dataset.definitionMode;$$('[data-definition-mode]').forEach(x=>x.classList.toggle('active',x===b));renderDefinitions()}));
$('#refresh-definitions').addEventListener('click',guarded(async()=>{await api('/api/ingest',{});toast('All sought definitions queued for a paced refresh')}));
for(const id of ['carrier','chiral','prayer']){$('#'+id+'-weight').addEventListener('input',event=>$('#'+id+'-weight-value').textContent=Number(event.target.value).toFixed(2));$('#'+id+'-weight').addEventListener('change',guarded(async event=>{await api('/api/weight',{id,weight:Number(event.target.value)});const n=state.neural.nodes.find(n=>n.id===id);if(n)n.weight=Number(event.target.value);toast(`${id==='prayer'?'Intention':id[0].toUpperCase()+id.slice(1)} weight saved`)}));}
$('#learning-toggle').addEventListener('click',guarded(async()=>{const r=await api('/api/settings',{learning:!state.settings.learning});state.settings=r.settings;renderAll()}));
$('#chiral-toggle').addEventListener('click',guarded(async()=>{const r=await api('/api/settings',{chiral_running:!state.settings.chiral_running});state.settings=r.settings;renderAll()}));
$('#chiral-step').addEventListener('click',guarded(async()=>{await api('/api/settings',{chiral_running:false});state.chiral={...state.chiral,...await api('/api/chiral',{action:'step'})};renderAll()}));
$('#chiral-reset').addEventListener('click',guarded(async()=>{await api('/api/settings',{chiral_running:false});state.chiral={...state.chiral,...await api('/api/chiral',{action:'reset'})};renderAll();toast('Exact seed restored · loop paused')}));
$('#reduce-motion').addEventListener('change',event=>{reduced=event.target.checked;localStorage.setItem('postscarcity-reduced',String(reduced))});
$('#settings-form').addEventListener('submit',guarded(async event=>{event.preventDefault();const data={};for(const input of event.target.elements){if(!input.name)continue;data[input.name]=input.type==='checkbox'?input.checked:Number(input.value);}$('#settings-status').textContent='Applying…';const result=await api('/api/settings',data);state.settings=result.settings;$('#settings-status').textContent='Settings saved';if(new URL(result.url).port!==location.port){toast('Port updated. Reconnecting…');setTimeout(()=>location.assign(result.url+'/#settings'),350);}else toast('Settings saved')}));
$('#stop-runtime').addEventListener('click',guarded(async()=>{await api('/api/stop',{});source?.close();$('#connection').textContent='RUNTIME STOPPED';$('#connection').classList.add('offline');toast('Runtime stopped. Use the launcher to start it again.')}));

async function openModule(id){selected=id;$$('[data-detail-tab]').forEach(b=>b.classList.toggle('active',b.dataset.detailTab==='results'));for(const tab of ['results','inputs','source'])$('#detail-'+tab).hidden=tab!=='results';$('#module-source').textContent='';await refreshDetail(true);if(!$('#module-dialog').open)$('#module-dialog').showModal();}
async function refreshDetail(resetInputs){try{const id=selected;const data=await api('/api/module?id='+encodeURIComponent(id));if(id!==selected)return;const m=data.module;$('#drawer-title').textContent=m.title;$('#drawer-family').textContent=m.family.toUpperCase()+' / '+(m.input_basis||'Rule calculation');$('#drawer-description').textContent=m.description;$('#drawer-state').textContent=stateText(m);$('#drawer-time').textContent=m.last_run?shortTime(m.last_run)+' · '+m.duration_ms+' ms':'No result yet';$('#detail-animation').dataset.mini=m.family;$('#detail-animation').dataset.seed=seed(m.id);$('#module-results').textContent=data.result?JSON.stringify(data.result,null,2):'Waiting for the first execution.';if(resetInputs){$('#module-inputs').value=JSON.stringify(data.inputs,null,2);$('#save-inputs').disabled=!Object.keys(m.inputs).length;}}catch(e){toast(e.message)}}
$('#close-dialog').addEventListener('click',()=>$('#module-dialog').close());$('#module-dialog').addEventListener('click',e=>{if(e.target===$('#module-dialog')&&e.clientX<e.target.getBoundingClientRect().left)e.target.close()});
$('#run-module').addEventListener('click',guarded(async()=>{await api('/api/run',{id:selected});toast('Module queued')}));
$$('[data-detail-tab]').forEach(button=>button.addEventListener('click',guarded(async()=>{const tab=button.dataset.detailTab;$$('[data-detail-tab]').forEach(b=>b.classList.toggle('active',b===button));for(const name of ['results','inputs','source'])$('#detail-'+name).hidden=name!==tab;if(tab==='source')$('#module-source').textContent=(await api('/api/source?id='+encodeURIComponent(selected))).source;})));
$('#save-inputs').addEventListener('click',guarded(async()=>{const result=await api('/api/inputs',{id:selected,inputs:JSON.parse($('#module-inputs').value)});toast(result.scheduled?'Inputs saved; execution queued':'Inputs saved; they apply on the next pass')}));
$('#reset-inputs').addEventListener('click',()=>{$('#module-inputs').value=JSON.stringify(state.modules.find(m=>m.id===selected).inputs,null,2);toast('Original inputs restored in the editor. Save & run to apply.')});

function seed(text){let n=0;for(const c of text)n=(n*31+c.charCodeAt(0))>>>0;return n%1000;}
function canvasSize(canvas){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return null;const ratio=Math.min(devicePixelRatio||1,2);const w=Math.round(rect.width*ratio),h=Math.round(rect.height*ratio);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,rect.width,rect.height);return{ctx,w:rect.width,h:rect.height};}
function circle(ctx,x,y,r,color,fill=false){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx[fill?'fillStyle':'strokeStyle']=color;fill?ctx.fill():ctx.stroke();}
function line(ctx,x,y,xx,yy,color){ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(xx,yy);ctx.stroke();}
function drawNetwork(t){const size=canvasSize($('#network'));if(!size||!state)return;const{ctx,w,h}=size,cx=w/2,cy=h/2,R=Math.min(w*.33,h*.35),cluster=Math.min(37,w/14),colorsAlpha='38';ctx.lineWidth=.65;points=[];
  for(let ring=0;ring<3;ring++){ctx.setLineDash(ring===1?[2,7]:[]);circle(ctx,cx,cy,R+cluster+15+ring*12,'#31495455');}ctx.setLineDash([]);circle(ctx,cx,cy,Math.min(65,R*.47),'#73ad9855');circle(ctx,cx,cy,Math.min(70,R*.51),'#73ad981a');
  for(let f=0;f<families.length;f++){const family=families[f],color=colors[family],angle=-Math.PI/2+f*Math.PI/3,hubx=cx+Math.cos(angle)*R,huby=cy+Math.sin(angle)*R;const list=state.modules.filter(m=>m.family===family);line(ctx,cx+Math.cos(angle)*70,cy+Math.sin(angle)*70,hubx,huby,color+'35');circle(ctx,hubx,huby,cluster*.65,color+'24');
    list.forEach((m,i)=>{const a=i/list.length*Math.PI*2+t*.017*(f%2?1:-1),radius=cluster*(.86+(i%3)*.08),x=hubx+Math.cos(a)*radius,y=huby+Math.sin(a)*radius,activation=state.neural.nodes.find(n=>n.id==='module:'+m.id)?.activation||0;line(ctx,hubx,huby,x,y,color+'45');const q=(t*.16+i*.13)%1;circle(ctx,hubx+(x-hubx)*q,huby+(y-huby)*q,1.15,color+'9a',true);const recent=m.status==='running',r=2.8+Math.abs(activation)*1.8;circle(ctx,x,y,r+4,recent?color+'35':color+'10',true);circle(ctx,x,y,r,m.status==='error'?'#ed8069':color+(m.runs?'df':'4a'),true);if(m.gate===1){ctx.strokeStyle=color+'99';ctx.strokeRect(x-6,y-6,12,12)}points.push({x,y,m});});circle(ctx,hubx,huby,3,color+'bf',true);
    const q=(t*.13+f/6)%1;circle(ctx,cx+(hubx-cx)*q,cy+(huby-cy)*q,1.5,color+'ac',true);
  }
  ctx.setLineDash([4,13]);ctx.strokeStyle='#a3edcb25';ctx.beginPath();ctx.ellipse(cx,cy,R+cluster+25,(R+cluster)*.5,t*.013,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);
}
$('#network').addEventListener('mousemove',event=>{const rect=event.target.getBoundingClientRect();const x=event.clientX-rect.left,y=event.clientY-rect.top,p=points.find(p=>Math.hypot(p.x-x,p.y-y)<12);const tip=$('#graph-tip');tip.style.display=p?'block':'none';if(p){tip.textContent=p.m.title+' · '+stateText(p.m);tip.style.left=Math.min(rect.width-220,Math.max(8,x+14))+'px';tip.style.top=Math.max(10,y-40)+'px';}});
$('#network').addEventListener('mouseleave',()=>$('#graph-tip').style.display='none');$('#network').addEventListener('click',event=>{const r=event.target.getBoundingClientRect(),p=points.find(p=>Math.hypot(p.x-(event.clientX-r.left),p.y-(event.clientY-r.top))<15);if(p)openModule(p.m.id)});
function drawWave(t){const size=canvasSize($('#wave'));if(!size)return;const{ctx,w,h}=size;for(let row=1;row<4;row++)line(ctx,0,h*row/4,w,h*row/4,'#23374270');ctx.strokeStyle='#a3edcb';ctx.lineWidth=1.2;ctx.beginPath();const weight=Number($('#carrier-weight').value);for(let x=0;x<=w;x++){const y=h/2+Math.sin(x/w*Math.PI*2*7.83-t*2)*Math.min(26,Math.abs(weight)*15);x?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();}
function drawMini(canvas,t){const size=canvasSize(canvas);if(!size)return;const{ctx,w,h}=size,family=canvas.dataset.mini,color=colors[family]||colors.Registry,s=Number(canvas.dataset.seed||0),cx=w/2,cy=h/2,r=Math.min(h*.35,w*.28);ctx.lineWidth=1;
  if(family==='Registry'){for(let i=0;i<9;i++){const x=cx+(i%3-1)*r*.85,y=cy+(Math.floor(i/3)-1)*r*.7;ctx.strokeStyle=color+'45';ctx.strokeRect(x-5,y-5,10,10);circle(ctx,x,y,1.4+Math.sin(t+i+s)*.5,color+'bb',true);if(i<8)line(ctx,x,y,cx+((i+1)%3-1)*r*.85,cy+(Math.floor((i+1)/3)-1)*r*.7,color+'22');}}
  else if(family==='Logic'){const pts=[0,1,2].map(i=>[cx+Math.cos(i*Math.PI*2/3-Math.PI/2)*r,cy+Math.sin(i*Math.PI*2/3-Math.PI/2)*r]);for(let i=0;i<3;i++){const p=pts[i],q=pts[(i+1)%3];line(ctx,...p,...q,color+'7a');circle(ctx,...p,5,color+'aa');const u=(t*.4+s*.01)%1;circle(ctx,p[0]+(q[0]-p[0])*u,p[1]+(q[1]-p[1])*u,2,color,true);}ctx.font='9px Consolas';ctx.fillStyle=color;ctx.textAlign='center';ctx.fillText('±1',cx,cy+4);}
  else if(family==='Safeguard'){for(let i=0;i<3;i++){ctx.beginPath();ctx.strokeStyle=color+(i===1?'a0':'45');ctx.arc(cx,cy,r*(.5+i*.3),t*.2+i,Math.PI*1.5+t*.2+i);ctx.stroke();}line(ctx,cx-5,cy,cx-1,cy+4,color);line(ctx,cx-1,cy+4,cx+7,cy-6,color);}
  else if(family==='Telemetry'){for(let k=0;k<2;k++){ctx.beginPath();ctx.strokeStyle=color+(k?'50':'c0');for(let x=-r*2;x<r*2;x++){const y=Math.sin(x/r*4+t*(k+1)*.8+s)*r*.55*Math.sin((x+r*2)/(r*4)*Math.PI);x===-r*2?ctx.moveTo(cx+x,cy+y):ctx.lineTo(cx+x,cy+y+k*5);}ctx.stroke();}}
  else if(family==='Covenant'){for(let i=0;i<3;i++){ctx.beginPath();ctx.strokeStyle=color+(i===1?'ba':'50');ctx.ellipse(cx,cy,r*1.2,r*.43,t*.1+i*Math.PI/3,0,Math.PI*2);ctx.stroke();}circle(ctx,cx,cy,3,color,true);}
  else{for(let i=0;i<5;i++){const x=(i-2)*r*.6;ctx.strokeStyle=color+'55';ctx.beginPath();ctx.moveTo(cx,cy+r*.8);ctx.quadraticCurveTo(cx+x,cy,cx+x+Math.sin(t*.3+i)*3,cy-r*.7);ctx.stroke();circle(ctx,cx+x+Math.sin(t*.3+i)*3,cy-r*.7,2.5,color+'bb',true);}circle(ctx,cx,cy+r*.8,3,color,true);}
}
function drawChiral(t){const size=canvasSize($('#chiral-canvas'));if(!size||!state)return;const{ctx,w,h}=size,c=state.chiral,cx=w/2,cell=Math.min(38,w*.07),gap=Math.min(45,(h-50)/8),top=(h-gap*7)/2,left=w*.12,right=w*.63;
  ctx.strokeStyle='#3f626855';ctx.setLineDash([3,7]);line(ctx,cx,25,cx,h-25,'#3f626855');ctx.setLineDash([]);
  for(let row=0;row<8;row++){const y=top+row*gap;ctx.strokeStyle='#28413d55';ctx.beginPath();ctx.moveTo(left+cell*3,y);ctx.bezierCurveTo(cx-20,y+Math.sin(t*.7+row)*15,cx+20,y-Math.sin(t*.7+row)*15,right,y);ctx.stroke();const travel=(t*.24+row*.11)%1,px=left+cell*3+(right-left-cell*3)*travel;circle(ctx,px,y,1.4,'#a3edcb85',true);
    for(const [side,rows,start,color]of [['L',c.left,left,'#a3edcb'],['R',c.right,right,'#eac386']])rows[row].forEach((bit,col)=>{const x=start+col*cell;if(bit===null){circle(ctx,x,y,1,'#40545e70',true);return;}const radius=Math.min(14,cell*.35);ctx.fillStyle=bit===1?color+'24':'#12202a';ctx.strokeStyle=bit===1?color+'d0':color+'40';ctx.beginPath();ctx.roundRect(x-radius,y-radius,radius*2,radius*2,5);ctx.fill();ctx.stroke();ctx.font=`${Math.max(11,radius)}px Consolas`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=bit===1?color:'#738694';ctx.fillText(bit,x,y+1);});
  }
  const alpha=.25+Math.abs(c.drive)*.45;circle(ctx,cx,h/2,18,`rgba(163,237,203,${alpha})`);circle(ctx,cx,h/2,25,'#a3edcb18');ctx.fillStyle='#a3edcb';ctx.font='20px Georgia';ctx.textAlign='center';ctx.fillText('·',cx,h/2+1);ctx.textBaseline='alphabetic';ctx.font='9px Consolas';ctx.fillStyle='#91aca7';ctx.fillText(c.shift<0?'← REVERSE →':c.shift===0?'HOLD':'→ GENERATE ←',cx,h-15);
}
function animate(time){frame++;const t=reduced?0:time/1000;if(!reduced||frame%20===0){if(activeView==='field'){drawNetwork(t);drawWave(t);}if(activeView==='chiral')drawChiral(t);for(const canvas of $$('.view.active [data-mini],dialog[open] [data-mini]'))drawMini(canvas,t);}requestAnimationFrame(animate);}

function buildModelPanels(){const names={llama:'Llama 3',gemini:'Gemini',chatgpt:'ChatGPT'};$('#model-panels').innerHTML=Object.entries(names).map(([id,name])=>`<article class="panel model-panel" data-provider="${id}"><header><div><span class="tiny-label">${id==='llama'?'LOCAL · OLLAMA':id==='gemini'?'GOOGLE API':'OPENAI API'}</span><h2>${name}</h2></div><span class="tag model-status">CHECKING</span></header><details class="model-config"><summary>Connection settings</summary><label>Model<input class="model-name" aria-label="${name} model"></label>${id==='llama'?'<p>Uses the installed Llama 3 model at localhost:11434.</p>':`<label>${id==='gemini'?'Gemini':'OpenAI'} API key<input class="model-key" type="password" autocomplete="off" placeholder="Enter key for this runtime session" aria-label="${name} API key"></label><p>Keys stay in server memory and are not saved to disk.</p>`}<div class="button-row"><button class="button model-save">Save connection</button><button class="button model-check">Test</button></div></details><div class="model-history" role="log" aria-label="${name} conversation"><p class="empty">Your conversation with ${name} begins here.</p></div><div class="model-error" role="status"></div><div class="model-coverage">Shared neural context is included automatically.</div><form class="model-compose"><textarea class="model-input" placeholder="Ask ${name} about the field…" aria-label="Message to ${name}" maxlength="5000" required></textarea><div><button type="button" class="link-button model-clear">Clear chat</button><button type="submit" class="button primary model-send">Send ↗</button></div></form></article>`).join('');$$('.model-panel').forEach(panel=>{const provider=panel.dataset.provider;$('.model-save',panel).addEventListener('click',guarded(async()=>{const data={provider,model:$('.model-name',panel).value};const key=$('.model-key',panel);if(key&&key.value)data.key=key.value;await api('/api/models/configure',data);if(key)key.value='';await refreshModels();toast('Connection settings saved')}));$('.model-check',panel).addEventListener('click',guarded(async()=>{const button=$('.model-check',panel);button.disabled=true;try{await api('/api/models/check',{provider});toast('Provider connection confirmed');await refreshModels()}finally{button.disabled=false}}));$('.model-clear',panel).addEventListener('click',guarded(async()=>{await api('/api/models/clear',{provider});await refreshModels()}));$('.model-compose',panel).addEventListener('submit',guarded(async event=>{event.preventDefault();const input=$('.model-input',panel);const text=input.value;await api('/api/models/send',{provider,message:text,source_ids:window.selectedSources?.('chat-sources')||[]});input.value='';await refreshModels()}));$('.model-input',panel).addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();$('.model-compose',panel).requestSubmit()}});});}
