async function refreshModels(){if(refreshingModels)return;refreshingModels=true;try{modelState=await api('/api/models');for(const panel of $$('.model-panel')){const data=modelState[panel.dataset.provider];$('.model-status',panel).textContent=data.busy?'THINKING':!data.configured?'KEY NEEDED':data.status.toUpperCase();$('.model-status',panel).classList.toggle('mint',data.status==='connected');const name=$('.model-name',panel);if(document.activeElement!==name)name.value=data.model;$('.model-send',panel).disabled=data.busy;$('.model-send',panel).textContent=data.busy?'Thinking…':'Send ↗';$('.model-clear',panel).disabled=data.busy;$('.model-error',panel).textContent=data.error||'';const history=$('.model-history',panel),html=data.messages.map(m=>`<div class="chat-message ${m.role}"><span>${m.role==='user'?'YOU':panel.dataset.provider.toUpperCase()}</span><p>${escapeHTML(m.content)}</p></div>`).join('')||'<p class="empty">Ask about any module, the neural rules, or the chiral process.</p>';if(history.innerHTML!==html){const atBottom=history.scrollHeight-history.scrollTop-history.clientHeight<70;history.innerHTML=html;if(atBottom)history.scrollTop=history.scrollHeight;}if(data.context)$('.model-coverage',panel).textContent=`${data.context.shared_rules} neural rules · ${data.context.module_summaries} module summaries · snapshot ${data.context.snapshot_time} UTC${data.context.prompt_tokens?' · '+data.context.prompt_tokens+' prompt tokens':''}`;}window.voiceModels?.(modelState);}catch(error){toast(error.message)}finally{refreshingModels=false}}
