v3State=await api('/api/v3');v3Agent=await api('/api/v3/agent');const s=v3State;
$('#v3-core-layer').textContent=s.core?.layer||'READY';$('#v3-core-caption').textContent=s.core?`Cycle ${number(s.core.cycle)} · output ${s.core.output.toFixed(3)} · calculated stability ${s.core.stability.toFixed(2)} · floor target ${s.core.eco_floor}`:'Waiting for the live core.';
