const caseSignature=JSON.stringify(s.cases||[]);
if($('#v3-case-history')&&caseSignature!==caseRenderSignature){const expanded=new Set($$('#v3-case-history details[open]').map(e=>e.dataset.case));$('#v3-case-history').innerHTML=(s.cases||[]).slice().reverse().map(c=>`<details data-case="${c.id}" ${expanded.has(c.id)?'open':''}><summary>${escapeHTML(c.id)} · ${escapeHTML(c.result.status)}</summary><p><strong>Observation:</strong> ${escapeHTML(c.result.observation)}</p><p><strong>Allegation:</strong> ${escapeHTML(c.result.allegation||'None recorded')}</p><p><strong>Evidence:</strong> ${escapeHTML(c.result.evidence.join('; '))}</p><p><strong>Repair conditions:</strong> ${escapeHTML(c.result.unmet_repair_conditions||'Not recorded')}</p><p>${escapeHTML(c.result.legal_finding)}</p>${(c.human_decisions||[]).map(d=>`<blockquote>${escapeHTML(d.text)}<small>Source: ${escapeHTML(d.reference)} · ${escapeHTML(d.entered)}</small></blockquote>`).join('')}<button type="button" class="button" data-case-export="${c.id}">Export case record</button></details>`).join('')||'<p>No review cases recorded.</p>';caseRenderSignature=caseSignature;const select=$('#v3-human-case');if(select){const value=select.value;select.innerHTML=(s.cases||[]).map(c=>`<option value="${c.id}">${escapeHTML(c.id+' · '+c.result.status)}</option>`).join('');if([...select.options].some(o=>o.value===value))select.value=value;}}
