$('#v3-knowledge-status').textContent=`${number(s.knowledge.count)} files indexed · ${s.knowledge.scanning?'scanning':s.knowledge.updated||'not indexed yet'}${s.knowledge.truncated?' · limit reached':''}`;
$('#v3-code-folder').textContent=s.code_folder;$('#v3-revisions').innerHTML=s.revisions.slice().reverse().map(r=>`<button class="v3-file" data-name="${escapeHTML(r.name)}"><strong>${escapeHTML(r.name)}</strong><small>${r.bytes} bytes · syntax ${escapeHTML(r.syntax)} · ${escapeHTML(r.created)}</small></button>`).join('')||'<p>No Python files saved yet.</p>';
$$('#v3-revisions [data-name]').forEach(b=>b.addEventListener('click',guarded(async()=>{const r=await api('/api/v3/code-read',{name:b.dataset.name});reviewedCode=r;$('#v3-code-name').value=r.name;$('#v3-code-text').value=r.text;})));
if(state&&!$('#v3-connection-targets').options.length)$('#v3-connection-targets').innerHTML=state.modules.map(m=>`<option value="${escapeHTML(m.id)}">${escapeHTML(m.title)}</option>`).join('');
