function drawV3(t){
if(activeView==='laboratory'){const s=canvasSize($('#v3-orbits'));if(s){const{ctx,w,h}=s,cx=w/2,cy=h*.45,r=Math.min(w*.32,h*.31),cpu=(state?.host.cpu||0)/100,output=v3State?.core?.output||0;for(let j=0;j<7;j++){const angle=t*.08*(j%2?1:-1)+j*6.283/7,rr=r*(.5+j*.07);ctx.strokeStyle='#75ced12b';ctx.beginPath();ctx.ellipse(cx,cy,rr,rr*.48,j*.42,0,Math.PI*2);ctx.stroke();circle(ctx,cx+Math.cos(angle)*rr,cy+Math.sin(angle)*rr*.55,3+cpu*5,['#a3edcb','#eac386','#8bacde'][j%3],true);}circle(ctx,cx,cy,16+Math.abs(output)*18,'#a3edcb55',true);ctx.fillStyle='#a3edcb';ctx.textAlign='center';ctx.font='12px monospace';ctx.fillText('CPU '+(cpu*100).toFixed(1)+'% · CORE '+output.toFixed(3),cx,h-40);ctx.strokeStyle='#a3edcb';ctx.beginPath();v3Trace.forEach((v,i)=>{const x=i/100*w,y=h-15-v*25;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();}}
if(activeView==='chiral'){const s=canvasSize($('#v3-wave'));if(s){const{ctx,w,h}=s,values=v3State?.wav.waveform||[];ctx.strokeStyle='#a3edcb';ctx.beginPath();values.forEach((v,i)=>{const x=i/Math.max(1,values.length-1)*w,y=h*.8-v*h*.65;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();const m=state?.carrier.modulation||v3State?.wav;if(m&&v3State?.wav.duration){const x=m.position/v3State.wav.duration*w;line(ctx,x,0,x,h,'#eac386');}ctx.fillStyle='#789b97';ctx.font='12px monospace';ctx.fillText('MEASURED RMS ENVELOPE',14,22);}}
