'use strict';
Object.assign(titleMap,{reality:'Reality & toggles',watch:'Internet watch',fulfilment:'Resources & delivery'});
let realityState=null,watchState=null,resourceState=null,resourcePreview=null,watchFormLoaded=false;
const rwPages={
reality:v3Heading('BOOLEAN IMPRINT · OBSERVED STATE','What is actually working','Each flag describes a specific capability. An enabled calculation is not proof of physical change.')+`
<article class="panel extension-form"><p><strong>Implemented</strong>: a working code path. <strong>Enabled</strong>: its gate/configuration is present. <strong>Active</strong>: running or scheduled. <strong>Verified</strong>: evidence for the scope written on that card.</p><p>False may mean “not run yet”, “needs setup” or “not implemented”; the explanation identifies which. There is no single switch that turns a calculation into an external action.</p><div class="button-row"><button class="button" id="rw-refresh">Refresh evidence</button><button class="button" id="rw-export">Export boolean imprint</button></div><p id="rw-stamp" class="muted"></p></article><div id="rw-capabilities" class="rw-cards"></div><details class="panel extension-form"><summary>All 80 module execution states</summary><div id="rw-modules"></div></details>`,
watch:v3Heading('PUBLIC SOURCES → EVIDENCE → REVIEW','Internet opportunity watch','Find leads related to human needs, resource access and waste reduction. Keep each conclusion tied to its source.')+`
<div class="v3-grid"><form id="rw-watch-form" class="panel extension-form"><h2>Continuous watch</h2><label class="check"><input type="checkbox" name="enabled"> Keep watching while the app runs</label><label class="check"><input type="checkbox" name="public_search"> Search public GOV.UK information</label><label class="check"><input type="checkbox" name="include_sources"> Review sources added in Website & text</label><label class="check"><input type="checkbox" name="read_pages"> Read discovered public pages (up to 12 per scan)</label><label class="check"><input type="checkbox" name="create_briefs"> Save useful work briefs locally</label><label>Topics · one per line<textarea name="topics" required maxlength="726"></textarea></label><label>Minutes between scans<input name="minutes" type="number" min="5" max="1440" value="15" required></label><div class="button-row">${v3Button('Save watch settings')}<button type="button" class="button" id="rw-scan">Scan now</button></div><p>Starts with public UK sources as an editable starting scope. Add other public websites through Website & text. Search terms may be sent to GOV.UK. Ingestion must be enabled for scheduled scans.</p><p>Rules prioritise relevant leads and protect your own resource plans. They do not establish guilt, impose law or take action against websites.</p></form><article class="panel extension-form"><h2>Observed activity</h2><div id="rw-watch-status"></div><button class="button" id="rw-report">Download research report</button><p>The report is also saved in the app work folder and available as a model source. Search descriptions are leads: check deadlines, location, eligibility, costs and whether support remains available.</p></article></div><div id="rw-findings" class="rw-cards"></div>`,
fulfilment:v3Heading('ACTUAL RECORDS · PROTECTED RESERVES','Resources into useful work','Import observed stock and needs, reserve eligible surplus, and record what people actually delivered.')+`
<div class="v3-grid"><form id="rw-import" class="panel extension-form"><h2>Import observed inventory</h2><label>Resource unit<input name="unit" required maxlength="40" placeholder="meals, kg, hours…"></label><label>Source reference<input name="reference" required maxlength="2000" placeholder="Inventory count or source document"></label><label>When was it observed?<input name="observed" type="datetime-local" required></label><label>Load CSV<input id="rw-csv-file" type="file" accept=".csv,text/csv"></label><label>CSV contents<textarea name="csv" class="v3-code" required maxlength="200000" placeholder="kind,id,amount,floor,protected_earnings,protected_top,priority"></textarea></label><small>kind is stock or need. IDs must be unique. amount is available stock or unmet need. Keep one resource unit per inventory. Protected amounts use the greatest value, not their sum.</small>${v3Button('Import inventory')}<p>Import replaces the current inventory. Open reservations must be completed or cancelled first. Earlier receipts remain in the ledger.</p></form><article class="panel extension-form"><h2>Review an allocation</h2><div id="rw-inventory-summary"></div><div class="button-row"><button class="button" id="rw-preview">Calculate from inventory</button><button class="button primary" id="rw-reserve" disabled>Reserve this allocation</button></div><pre id="rw-plan" class="v3-output">Import your own records. No sample stock is active.</pre><p>Reservations are real local bookkeeping. They prevent double booking inside this app; they do not synchronise an external warehouse or move physical goods.</p><button class="button" id="rw-ledger-export">Export inventory and work orders</button><button class="button" id="rw-ledger-verify">Verify receipt chain</button><p id="rw-ledger-check"></p></article></div>
<div class="v3-grid"><form id="rw-delivery" class="panel extension-form"><h2>Close a reservation</h2><label>Open reservation<select name="id" id="rw-order-select" required></select></label><label>Responsible person<input name="reviewer" required maxlength="120"></label><label>Delivery evidence or cancellation reason<textarea name="reference" required maxlength="2000"></textarea></label><label>Action<select name="action"><option value="deliver">Record human-confirmed delivery</option><option value="cancel">Cancel and release reservation</option></select></label>${v3Button('Save record')}<p>Delivery records are attributed human reports. The app does not independently authenticate the evidence or claim that goods moved merely because a plan ran.</p></form><article class="panel extension-form"><h2>Work orders</h2><div id="rw-orders"></div></article></div><p id="rw-resource-result" role="status"></p>`
};
for(const [id,html] of Object.entries(rwPages)){
  const section=document.createElement('section');section.id=id;section.className='view';section.innerHTML=html;$('main footer').before(section);
  const button=document.createElement('button');button.dataset.view=id;button.innerHTML=`<span>◎</span> ${escapeHTML(titleMap[id])}`;button.title=titleMap[id];$('nav [data-view=settings]').before(button);
  button.addEventListener('click',()=>{showView(id);refreshRealWorld().catch(e=>toast(e.message));});
}
function rwDownload(name,content,type='application/json'){const link=document.createElement('a');const url=URL.createObjectURL(new Blob([typeof content==='string'?content:JSON.stringify(content,null,2)],{type}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function rwFlag(name,value){return `<span class="rw-flag ${value?'rw-true':'rw-false'}">${escapeHTML(name)} <strong>${value?'TRUE':'FALSE'}</strong></span>`;}
function rwSafeLink(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function rwReplace(id,html){const el=$('#'+id);if(el.dataset.signature===html)return;const top=el.scrollTop;el.innerHTML=html;el.dataset.signature=html;el.scrollTop=top;}
async function refreshRealWorld(){
  if(activeView==='reality'){
    const s=await api('/api/reality');realityState=s;
    $('#rw-stamp').textContent=`Observed ${s.generated_at} · port ${s.port} · ${s.worker_limit} workers`;
    rwReplace('rw-capabilities',s.capabilities.map(c=>`<article class="panel extension-form rw-card" data-capability="${c.id}"><h2>${escapeHTML(c.title)}</h2><div class="rw-flags">${['implemented','enabled','active','verified'].map(k=>rwFlag(k,c[k])).join('')}</div><p>${escapeHTML(c.scope)}</p>${c.additional_logic_or_setup?`<p class="muted">Needed: ${escapeHTML(c.additional_logic_or_setup)}</p>`:''}${c.control?`<label class="check"><input type="checkbox" data-rw-control="${c.control}" ${c.enabled?'checked':''}> Enabled</label>`:''}</article>`).join(''));
    rwReplace('rw-modules',s.modules.map(m=>`<div class="v3-receipt"><strong>${escapeHTML(m.id)}</strong><div class="rw-flags">${rwFlag('execution verified',m.execution_verified)}${rwFlag('awaiting input',m.awaiting_input)}${rwFlag('physical outcome verified',m.physical_outcome_verified)}</div><p>${escapeHTML(m.input_basis)}${m.error?' · '+escapeHTML(m.error):''}</p></div>`).join(''));
  }else if(activeView==='watch'){
    const s=await api('/api/watch');watchState=s;
    if(!watchFormLoaded){const f=$('#rw-watch-form');for(const k of ['enabled','public_search','include_sources','read_pages','create_briefs'])f.elements[k].checked=s[k];f.elements.topics.value=s.topics.join('\n');f.elements.minutes.value=s.interval/60;watchFormLoaded=true;}
    rwReplace('rw-watch-status',`<div class="rw-flags">${rwFlag('enabled',s.enabled)}${rwFlag('scanning',s.busy)}${rwFlag('source receipt',!!s.last_success)}</div><p>${escapeHTML(s.scope)}</p><p>${s.privacy.public_web_paused?'Public web activity is waiting for a verified private connection.':'Public reads use the verified Tor connection.'}</p><p>Scans: ${s.scans} · findings: ${s.findings.length}<br>Last scan: ${escapeHTML(s.last_scan||'Waiting')}<br>Last successful source read: ${escapeHTML(s.last_success||'None yet')}</p>${s.error?`<pre class="v3-output">${escapeHTML(JSON.stringify(s.error,null,2))}</pre>`:''}<p>Reports and findings persist locally. Closing the browser leaves the runtime active; stopping it pauses the watch.</p>`);
    rwReplace('rw-findings',s.findings.slice(0,100).map(f=>{const url=rwSafeLink(f.url);return `<article class="panel extension-form rw-card"><span class="tag">${escapeHTML(f.review_status.toUpperCase())}</span><h2>${escapeHTML(f.title)}</h2><p>${escapeHTML(f.text.slice(0,850))}</p><p class="muted">${escapeHTML(f.source_kind)} · retrieved ${escapeHTML(f.retrieved||'unknown')}<br>Categories: ${escapeHTML(f.assessment.categories.join(', ')||'resource lead')}<br>Terms to check: ${escapeHTML(f.assessment.review_terms.join(', ')||'Availability and eligibility')}</p><div class="rw-flags">${rwFlag('floor benefit verified',false)}${rwFlag('external action allowed',false)}</div>${url?`<a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">Open original source ↗</a>`:''}<p>${escapeHTML(f.next_step)}</p><div class="button-row"><button class="button" data-finding="${f.id}" data-status="reviewed">Mark reviewed</button><button class="button" data-finding="${f.id}" data-status="dismissed">Dismiss</button></div></article>`;}).join('')||'<p class="panel extension-form">No findings yet. Scan public sources or add relevant websites/text.</p>');
  }else if(activeView==='fulfilment'){
    const s=await api('/api/resources');resourceState=s;
    if(resourcePreview&&resourcePreview.revision!==s.revision){resourcePreview=null;$('#rw-reserve').disabled=true;$('#rw-plan').textContent='Inventory changed. Calculate a fresh allocation before reserving.';}
    $('#rw-inventory-summary').textContent=`Revision ${s.revision} · ${s.stock.length} stock records · ${s.needs.length} need records · ${s.unit||'No unit yet'}`;
    const selected=$('#rw-order-select').value;const options=s.orders.filter(o=>o.status==='reserved').map(o=>`<option value="${o.id}">${o.id} · ${o.transfers.length} allocation(s)</option>`).join('');
    rwReplace('rw-order-select',options||'<option value="">No open reservations</option>');if([...$('#rw-order-select').options].some(o=>o.value===selected))$('#rw-order-select').value=selected;
    rwReplace('rw-orders',s.orders.slice().reverse().slice(0,50).map(o=>`<details class="v3-receipt"><summary>${escapeHTML(o.id)} · ${escapeHTML(o.status)}</summary><pre class="v3-output">${escapeHTML(JSON.stringify(o,null,2))}</pre></details>`).join('')||'<p>No work orders yet.</p>');
  }
}
$('#rw-capabilities').addEventListener('change',guarded(async e=>{const control=e.target.dataset.rwControl;if(!control)return;e.target.disabled=true;try{if(control==='watch')await api('/api/watch/configure',{enabled:e.target.checked});else await api('/api/settings',{[control]:e.target.checked});}finally{await refreshRealWorld();e.target.disabled=false;}}));
$('#rw-refresh').addEventListener('click',guarded(refreshRealWorld));
$('#rw-export').addEventListener('click',guarded(async()=>rwDownload('boolean-imprint.json',await api('/api/reality'))));
$('#rw-watch-form').addEventListener('submit',guarded(async e=>{e.preventDefault();const f=e.target;await api('/api/watch/configure',{enabled:f.elements.enabled.checked,public_search:f.elements.public_search.checked,include_sources:f.elements.include_sources.checked,read_pages:f.elements.read_pages.checked,create_briefs:f.elements.create_briefs.checked,interval:Math.round(Number(f.elements.minutes.value)*60),topics:f.elements.topics.value.split(/\r?\n/).map(t=>t.trim()).filter(Boolean)});toast('Watch settings saved');await refreshRealWorld();}));
$('#rw-scan').addEventListener('click',guarded(async e=>{e.target.disabled=true;e.target.textContent='Reading sources…';try{await api('/api/watch/scan',{});await refreshRealWorld();}finally{e.target.disabled=false;e.target.textContent='Scan now';}}));
$('#rw-report').addEventListener('click',guarded(async()=>rwDownload('opportunity-report.md',(await api('/api/watch/report')).text,'text/markdown')));
$('#rw-findings').addEventListener('click',guarded(async e=>{const b=e.target.closest('[data-finding]');if(!b)return;await api('/api/watch/review',{id:b.dataset.finding,status:b.dataset.status});await refreshRealWorld();}));
$('#rw-csv-file').addEventListener('change',guarded(async e=>{const f=e.target.files[0];if(!f||f.size>200000)throw Error('Choose a CSV up to 200 KB');$('#rw-import [name=csv]').value=await f.text();}));
$('#rw-import').addEventListener('submit',guarded(async e=>{e.preventDefault();if(!resourceState)await refreshRealWorld();const d=Object.fromEntries(new FormData(e.target));const r=await api('/api/resources/import',{csv:d.csv,unit:d.unit,reference:d.reference,observed_at:new Date(d.observed).toISOString(),revision:resourceState.revision,request_id:crypto.randomUUID()});$('#rw-resource-result').textContent=r.status;resourcePreview=null;$('#rw-reserve').disabled=true;$('#rw-plan').textContent='Inventory imported. Calculate an allocation.';await refreshRealWorld();}));
$('#rw-preview').addEventListener('click',guarded(async()=>{resourcePreview=await api('/api/resources/preview');$('#rw-plan').textContent=JSON.stringify(resourcePreview,null,2);$('#rw-reserve').disabled=!resourcePreview.plan.transfers.length;}));
$('#rw-reserve').addEventListener('click',guarded(async e=>{if(!resourcePreview)throw Error('Calculate and review an allocation first');e.target.disabled=true;try{const r=await api('/api/resources/reserve',{revision:resourcePreview.revision,request_id:crypto.randomUUID()});$('#rw-resource-result').textContent='Reserved work order '+r.order.id;resourcePreview=null;$('#rw-plan').textContent=JSON.stringify(r,null,2);await refreshRealWorld();}catch(error){resourcePreview=null;throw error;}}));
$('#rw-delivery').addEventListener('submit',guarded(async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const r=await api('/api/resources/'+d.action,{id:d.id,reviewer:d.reviewer,reference:d.reference,revision:resourceState.revision,request_id:crypto.randomUUID()});$('#rw-resource-result').textContent=r.status;await refreshRealWorld();}));
$('#rw-ledger-export').addEventListener('click',guarded(async()=>rwDownload('resource-work-orders.json',await api('/api/resources'))));
$('#rw-ledger-verify').addEventListener('click',guarded(async()=>{$('#rw-ledger-check').textContent=JSON.stringify(await api('/api/resources/verify'));}));
setInterval(()=>{if(activeView in rwPages)refreshRealWorld().catch(()=>{});},3000);
if(location.hash.slice(1) in rwPages){showView(location.hash.slice(1));refreshRealWorld().catch(()=>{});}

'use strict';
Object.assign(titleMap,{signals:'Abstract signal studio',classifier:'Trainable model',mesh:'Model review mesh',pythonlineage:'Python lineage'});
let pythonState=null,pythonMigration=null,signalFormReady=false;
const pythonPages={
signals:v3Heading('HYDROGEN · EARTH · SUN','Abstract forms, actual bits','Three symbolic signal profiles share the 7.83 Hz software pulse and pass generated bytes into the chirals.')+`
<div class="v4-planets">${['hydrogen','earth','sun'].map(n=>`<article class="panel v4-planet"><h2>${n[0].toUpperCase()+n.slice(1)}</h2><canvas id="v4-${n}" aria-label="${n} abstract signal visual"></canvas><div id="v4-${n}-caption" class="v4-signal-caption">Awaiting a generated frame.</div></article>`).join('')}</div>
<div class="v3-grid"><form id="v4-signals" class="panel extension-form"><h2>Signal sources and weights</h2><label class="check"><input name="signals_enabled" type="checkbox"> Generate each pulse</label><label>Bit source<select name="source_mode"><option value="os_entropy">OS randomness mixed with selected inputs</option><option value="pattern">Deterministic abstract pattern</option></select></label><label class="check"><input name="ambient" type="checkbox"> Ingest accessible host readings</label><label class="check"><input name="mix_sources" type="checkbox"> Mix received source fingerprints</label>${['hydrogen','earth','sun'].map(n=>`<label>${n[0].toUpperCase()+n.slice(1)} influence<input name="${n}" type="number" min="-3" max="3" step="0.05" value="1"></label>`).join('')}${v3Button('Apply signal settings')}<p>OS randomness, deterministic patterns and ambient readings retain their own identities. App weights adapt through the existing neural layer; random bits do not by themselves supply meaningful training labels.</p></form><article class="panel extension-form"><h2>Ambient input receipts</h2><pre id="v4-ambient" class="v3-output"></pre><h2>Planetary observation</h2><button class="button" id="v4-noaa">Connect NOAA feed</button><pre id="v4-planetary" class="v3-output">Not connected.</pre><p>NOAA supplies geomagnetic K-index data. It does not measure a local Schumann frequency. No sensor value is invented when a connection fails.</p></article></div>
<div class="v3-grid"><form id="v4-ternary" class="panel extension-form"><h2>Balanced ternary matrix</h2><label>Vectors as JSON<textarea name="input" required placeholder='{"a":[1,0,-1],"b":[1,1,-1]}'></textarea></label>${v3Button('Calculate ternary result')}<pre id="v4-ternary-result" class="v3-output">Awaiting vectors.</pre></form><form id="v4-optimize" class="panel extension-form"><h2>Source weight optimiser</h2><label>Current and target weights<textarea name="input" required placeholder='{"current":[0.2,0.3],"target":[0.8,0.7],"rate":0.05}'></textarea></label>${v3Button('Calculate a gradient step')}<pre id="v4-optimize-result" class="v3-output">Awaiting weights.</pre><p>Preserves the original update rule. Its error measures distance to your target, not virtue or economic improvement.</p></form></div>`,
classifier:v3Heading('2 → 12 → 8 → 1 · BACKPROPAGATION + ADAM','A model that actually learns','Train the preserved neural classifier on your labelled data. Inspect its decision surface, loss and held-out accuracy.')+`
<div class="v3-grid"><form id="v4-dataset" class="panel extension-form"><h2>Supply labelled examples</h2><label>Import CSV<input id="v4-data-file" type="file" accept=".csv,text/csv"></label><label>CSV: x,y,label<textarea name="csv" required class="v3-code" maxlength="240000" placeholder="x,y,label"></textarea></label><small>At least 20 unique points, at least 5 in each class. x and y must be normalised to −1…1; label is 0 or 1. A stratified 20% holdout stays outside training.</small>${v3Button('Load data & reset model')}</form><article class="panel extension-form"><h2>Training controls</h2><form id="v4-train"><label>Training steps<input name="steps" type="number" min="1" max="500" value="100" required></label>${v3Button('Train on imported examples')}</form><div id="v4-model-status"></div><div class="button-row"><button class="button" id="v4-checkpoint-save">Download model checkpoint</button></div><label>Restore model JSON<input id="v4-checkpoint-load" type="file" accept=".json,application/json"></label><p>This is a real small classifier, separate from Llama. A good holdout score is evidence for this dataset only. Model checkpoints contain numerical weights, not executable code.</p></article></div>
