function renderPythonMigration(){if(!pythonMigration)return;const q=$('#v4-migration-query').value.toLowerCase();const files=pythonMigration.files.filter(f=>(f.path+' '+JSON.stringify(f.classes)+' '+JSON.stringify(f.functions)+' '+JSON.stringify(f.calls)).toLowerCase().includes(q));rwReplace('v4-migration-files',files.slice(0,60).map(f=>`<details class="v3-receipt"><summary><strong>${escapeHTML(f.path)}</strong><p>${escapeHTML(f.status)}</p></summary><p>${f.lines} lines · ${f.classes.length} classes · ${f.functions.length} functions · ${f.calls.length} calls</p><pre class="v3-output">${escapeHTML(JSON.stringify({classes:f.classes,functions:f.functions,calls:f.calls,syntax_error:f.syntax_error},null,2))}</pre></details>`).join('')||'<p>No matching source.</p>');}
async function refreshPython(){
 if(activeView==='pythonlineage'){
  if(!pythonMigration)pythonMigration=await api('/api/v4/migration');const s=pythonMigration.summary;$('#v4-migration-summary').textContent=`${s.python_files} Python files · ${s.classes} classes · ${s.functions} functions · ${s.call_sites} calls · ${s.duplicate_groups} duplicate groups · ${s.syntax_errors} invalid source files · ${s.total_modules} scheduled modules`;renderPythonMigration();return;
 }
 if(!(activeView in pythonPages))return;pythonState=await api('/api/v4');const s=pythonState;
 if(activeView==='signals'){
  if(!signalFormReady){const f=$('#v4-signals');for(const key of ['signals_enabled','ambient','mix_sources'])f.elements[key].checked=s[key];f.elements.source_mode.value=s.source_mode;for(const key of ['hydrogen','earth','sun'])f.elements[key].value=s.weights[key];signalFormReady=true;}
  for(const n of ['hydrogen','earth','sun']){const f=s.signals[n];$('#v4-'+n+'-caption').textContent=f?`FRAME ${f.sequence} · ${f.source_mode}\n${(f.ones_fraction*100).toFixed(1)}% ones · chiral ${f.chiral_accepted?'accepted':'queue full'}\n${f.hex}`:'No frame yet';}
  $('#v4-ambient').textContent=JSON.stringify(s.ambient_readings,null,2);$('#v4-planetary').textContent=JSON.stringify(s.planetary,null,2);
 }else if(activeView==='classifier'){
  const c=s.classifier;rwReplace('v4-model-status',`<p>${c.steps} training steps · ${c.dataset?c.dataset.rows+' supplied examples · '+c.dataset.holdout_rows+' held out':'No dataset supplied'}</p>${c.holdout?`<p>Held-out accuracy: ${(c.holdout.accuracy*100).toFixed(1)}%<br>Held-out loss: ${c.holdout.loss.toFixed(5)}</p>`:''}`);drawClassifier();
 }else if(activeView==='mesh'){
  if(!$('#v4-mesh-sources').options.length){const sources=await api('/api/sources');$('#v4-mesh-sources').innerHTML=sources.filter(x=>x.status==='ready').map(x=>`<option value="${escapeHTML(x.id)}">${escapeHTML(x.title)}</option>`).join('');}
  rwReplace('v4-mesh-results',s.mesh.slice().reverse().map(r=>`<details class="v3-receipt"><summary>${escapeHTML(r.status)} · ${escapeHTML(r.reviewer)} · ${r.duration_ms} ms</summary><pre class="v3-output">${escapeHTML(JSON.stringify(r,null,2))}</pre></details>`).join('')||'<p>No review yet.</p>');
 }
}
function pythonCanvas(id){const c=$('#'+id);if(!c)return null;const r=c.getBoundingClientRect();if(r.width<1)return null;const scale=devicePixelRatio||1;if(c.width!==Math.round(r.width*scale)||c.height!==Math.round(r.height*scale)){c.width=Math.round(r.width*scale);c.height=Math.round(r.height*scale);}const ctx=c.getContext('2d');ctx.setTransform(scale,0,0,scale,0,0);ctx.clearRect(0,0,r.width,r.height);return {ctx,w:r.width,h:r.height};}
function drawSignals(ms){if(activeView==='signals'&&pythonState){for(const [index,name]of ['hydrogen','earth','sun'].entries()){const canvas=pythonCanvas('v4-'+name);if(!canvas)continue;const {ctx,w,h}=canvas,f=pythonState.signals[name];if(!f)continue;const cx=w/2,cy=h*.43,r=Math.min(w*.32,h*.30),phase=reduced?0:ms*.00025;ctx.lineWidth=1;ctx.strokeStyle='#35584c';
  if(name==='hydrogen'){for(let j=0;j<3;j++){ctx.save();ctx.translate(cx,cy);ctx.rotate(j*Math.PI/3+phase);ctx.beginPath();ctx.ellipse(0,0,r,r*.34,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#a5f0cb';ctx.beginPath();ctx.arc(Math.cos(phase*3)*r,Math.sin(phase*3)*r*.34,3,0,Math.PI*2);ctx.fill();ctx.restore();}}
  if(name==='earth'){for(let j=-3;j<=3;j++){ctx.beginPath();ctx.ellipse(cx,cy+j*r/4,Math.sqrt(Math.max(0,r*r-(j*r/4)**2)),r*.1,0,0,Math.PI*2);ctx.stroke();}for(let j=0;j<5;j++){ctx.beginPath();ctx.ellipse(cx,cy,r*Math.abs(Math.cos(j*Math.PI/5+phase)),r,0,0,Math.PI*2);ctx.stroke();}}
  for(let j=0;j<64;j++){const bit=Number(f.bits[j]),a=j*Math.PI/32+phase,rr=name==='sun'?r*(.6+bit*.35):r*(.25+bit*.12);ctx.strokeStyle=bit?'#b0f0cb':'#3f6660';ctx.beginPath();ctx.moveTo(cx+Math.cos(a)*rr,cy+Math.sin(a)*rr);ctx.lineTo(cx+Math.cos(a)*(rr+7),cy+Math.sin(a)*(rr+7));ctx.stroke();}
  const cell=Math.min(8,(w-24)/32),left=(w-cell*32)/2;for(let j=0;j<256;j++){ctx.fillStyle=f.bits[j]==='1'?'#a4edc7':'#18312e';ctx.fillRect(left+(j%32)*cell,h*.78+Math.floor(j/32)*cell,cell-1,cell-1);}
 }}requestAnimationFrame(drawSignals);}
function drawClassifier(){const s=pythonState?.classifier;if(!s)return;const c=pythonCanvas('v4-decision');if(c){const {ctx,w,h}=c;for(let i=0;i<s.probability_grid.length;i++){const p=s.probability_grid[i];ctx.fillStyle=`rgb(${Math.round(170*(1-p)+40*p)},${Math.round(75*(1-p)+145*p)},${Math.round(62*(1-p)+112*p)})`;ctx.fillRect((i%25)*w/25,Math.floor(i/25)*h/25,w/25+1,h/25+1);}s.points.forEach((p,i)=>{ctx.fillStyle=s.labels[i]?'#bdffe0':'#ffd4be';ctx.strokeStyle='#0d1518';ctx.beginPath();ctx.arc((p[0]+1)*w/2,(p[1]+1)*h/2,3,0,Math.PI*2);ctx.fill();ctx.stroke();});}const l=pythonCanvas('v4-loss');if(l&&s.history.length){const {ctx,w,h}=l;const max=Math.max(.01,...s.history.flatMap(p=>[p.train.loss,p.holdout.loss]));for(const [key,color]of [['train','#a7edc8'],['holdout','#eea68c']]){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();s.history.forEach((p,i)=>{const x=15+i*(w-30)/Math.max(1,s.history.length-1),y=h-20-p[key].loss/max*(h-40);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}}}
requestAnimationFrame(drawSignals);setInterval(()=>{if(activeView in pythonPages)refreshPython().catch(()=>{});},2000);
if(location.hash.slice(1) in pythonPages){showView(location.hash.slice(1));refreshPython().catch(()=>{});}

