async function refreshNetwork(){
 const epoch=networkEpoch;
 if(activeView==='privacy'){
  const s=await api('/api/privacy');if(networkMutation||epoch!==networkEpoch)return;$('#privacy-auto').checked=s.automatic;
  rwReplace('privacy-state',`<div class="rw-flags">${rwFlag('Tor running',s.tor_running)}${rwFlag('web paused',s.public_web_paused)}${rwFlag('selected Windows VPN connected',s.vpn_connected)}</div><p>Route: Windows / connected VPN<br>Public IP: ${escapeHTML(s.exit_ip||'Not checked')}<br>Last IP check: ${escapeHTML(s.last_check||'Not checked')}</p><p>${escapeHTML(s.vpn?.scope||'')}</p>${s.error||s.vpn?.error?`<p>${escapeHTML(s.error||s.vpn.error)}</p>`:''}`);
  const select=$('#vpn-profile'),chosen=select.value||s.profile||'';
  const options='<option value="">Choose a Windows VPN</option>'+(s.vpn?.profiles||[]).map(p=>`<option value="${escapeHTML(p.name)}">${escapeHTML(p.name)} · ${escapeHTML(p.status)}${p.split_tunnel?' · split tunnel':''}</option>`).join('');
  if(select.innerHTML!==options){select.innerHTML=options;select.value=chosen;}
  if(!vpnControlsReady){select.value=s.profile||'';$('#vpn-gate [name=require_vpn]').checked=s.vpn_required;vpnControlsReady=true;}
 }else if(activeView==='pathway'){
  const s=await api('/api/pathway'),r=s.last||{};$('#pathway-enabled').checked=s.enabled;$('#pathway-llama').checked=s.local_llama;
  rwReplace('pathway-state',`<div class="rw-flags">${rwFlag('enabled',s.enabled)}${rwFlag('processing',s.busy)}${rwFlag('queued',s.queued)}</div><p>${escapeHTML(s.beacon_destination)}</p><p>Completed attempts: ${s.runs}<br>Latest status: ${escapeHTML(r.status||'Waiting for evidence')}<br>Batch source receipts: ${r.source_context_receipts||0} / 80<br>Successful modules: ${r.successful_modules||0}<br>Local beacon receipt: ${r.local_beacon_seq||'None yet'}</p>${r.error||r.inference_error?`<p role="status">${escapeHTML(r.error||r.inference_error)}</p>`:''}`);
  const text=r.inference||'No inference yet. A local Llama connection and source evidence are required.';
  if($('#pathway-inference').textContent!==text){const el=$('#pathway-inference'),top=el.scrollTop;el.textContent=text;el.scrollTop=top;}
 }
}
