let fluxData=null,fluxSelected=null,fluxHold=false,fluxRefreshing=false,fluxLastGrid=null,fluxControlsReady=false,fluxSubmitting=false,fluxCommandError=false;
function fluxText(id,text){const el=$('#'+id);if(el.textContent!==text){const top=el.scrollTop;el.textContent=text;el.scrollTop=top;}}
function fluxDrawGrid(id,bits,other,columns){const el=$('#'+id);el.style.setProperty('--columns',columns);if(el.children.length!==bits.length){el.replaceChildren(...[...bits].map(()=>document.createElement('span')));}const zero=$('#flux-zero').checked;[...el.children].forEach((cell,i)=>{cell.textContent=bits[i];cell.className=(bits[i]==='0'?(zero?'zero':'quiet'):'one')+(other&&other[i]!==bits[i]?' changed':'');cell.title=`Bit ${i}: ${other&&other[i]!==bits[i]?other[i]+' → ':''}${bits[i]}`;});}
function fluxGrid(){if(!fluxData)return;const pattern=$('#flux-view').value==='pattern';const p=fluxData.preview||{};const before=pattern?fluxData.previous.join(''):p.input_bits||'0'.repeat(256);const after=pattern?fluxData.rows.join(''):p.output_bits||'0'.repeat(256);fluxDrawGrid('flux-grid-in',before,null,pattern?14:16);fluxDrawGrid('flux-grid-out',after,before,pattern?14:16);$('#flux-input-label').textContent=pattern?'Previous frame · 84 bits':'First '+before.length+' bits of this chunk';$('#flux-output-label').textContent=pattern?'Row shift '+fluxData.shift:'Chiral shift '+(p.shift??'—');$('#flux-inverse').textContent=pattern?'Rotation preserves bit count':p.inverse_verified?'✓ Inverse verified':'Waiting for actual bytes';$('#flux-caption').textContent=pattern?`Generation ${fluxData.generation.toLocaleString()} · 84 data bits + 4 explicit padding bits per queued frame. Pattern is generated data.`:`${p.stream||'Waiting for a stream'} · ${p.chunk_bytes||0} bytes in this chunk · showing up to 256 bits. Whole-bus counters include all processed bytes.`;}
function fluxReceipt(){if(fluxSubmitting)return;const job=(fluxData?.commands||[]).find(j=>j.id===fluxSelected)||(fluxData?.commands||[]).at(-1);if(!job)return;if(job.id===fluxSelected&&!fluxCommandError)$('#flux-command-status').textContent=job.stream?`${job.status.toUpperCase()} · ${job.processed_bytes} / ${job.input_bytes} bytes processed`:'Command executed.';$('#flux-return-state').textContent=job.status.toUpperCase();const text=job.stream?`${job.command}\n\n${job.status.toUpperCase()} · ${job.processed_bytes} / ${job.input_bytes} bytes\n${job.bit_count} original bits · ${job.padding_bits} padding bits\n\nINPUT\n${job.input_bits}\n\nOUTPUT\n${job.output_bits||'Waiting for a chiral step…'}\n\nHEX\n${job.output_hex||'—'}\n\n${job.status==='complete'?'Inverse check: '+(job.inverse_verified?'PASS':'FAIL'):'Inverse check pending completion'}\nOutput SHA-256: ${job.output_sha256||'pending'}`:job.command+'\n\n'+JSON.stringify(job.result,null,2);fluxText('flux-command-output',text);fluxText('flux-command-receipt',JSON.stringify(job,null,2));}
async function refreshFlux(){if(activeView!=='flux'||fluxRefreshing)return;fluxRefreshing=true;try{const value=await api('/api/flux'+($('#flux-stream').value?'?stream='+encodeURIComponent($('#flux-stream').value):''));if(!fluxHold){fluxData=value;fluxGrid();}else if(fluxData){fluxData.commands=value.commands;}else fluxData=value;$('#flux-live').textContent=value.chiral_running?'BUS PROCESSING':'BUS PAUSED';$('#flux-hz').textContent=(value.carrier.measured_hz||0).toFixed(2)+' Hz';$('#flux-queue').textContent=`${value.bus.pending_bytes.toLocaleString()} queued bytes · ${value.bus.rejected_frames} rejected frames`;$('#flux-bytes').textContent=value.observed_bytes.toLocaleString();$('#flux-changed').textContent=value.changed_bits.toLocaleString();$('#flux-crossings').textContent=value.zero_to_one.toLocaleString()+' / '+value.one_to_zero.toLocaleString();$('#flux-phase').textContent=value.mode.toUpperCase();$('#flux-pattern-state').textContent=`${value.running?'Generating':'Held'} · neural shift + influence = ${value.shift} · ${value.generation.toLocaleString()} frames · ${value.pattern_rejected} pattern frames rejected`;const select=$('#flux-stream'),chosen=select.value;const html='<option value="">Most recent stream</option>'+value.streams.map(s=>`<option value="${escapeHTML(s.id)}">${escapeHTML(s.id)} · ${s.bytes.toLocaleString()} B</option>`).join('');if(select.innerHTML!==html){select.innerHTML=html;if([...select.options].some(o=>o.value===chosen))select.value=chosen;}if(!fluxControlsReady){const f=$('#flux-controls');f.elements.mode.value=value.mode;f.elements.influence.value=value.influence;f.elements.running.checked=value.running;fluxControlsReady=true;}$('#flux-help').textContent=value.help.join('\n');fluxText('flux-hashes',`INPUT SHA-256\n${value.input_sha256}\n\nOUTPUT SHA-256\n${value.output_sha256}\n\nScope: concatenation of every observed chunk since this runtime started.\nObserved chunks: ${value.chunks}\nBus completed frames: ${value.bus.completed_frames}\nRejected bytes: ${value.bus.rejected_bytes}`);rwReplace('flux-command-history',value.commands.slice().reverse().map(j=>`<button type="button" class="button" data-flux-receipt="${j.id}">${escapeHTML(j.command.slice(0,36))} · ${escapeHTML(j.status)}</button>`).join(''));fluxReceipt();}finally{fluxRefreshing=false;}}
async function fluxSend(command){fluxSubmitting=true;fluxCommandError=false;$('#flux-return-state').textContent='SUBMITTING';$('#flux-command-status').textContent='Submitting command…';$('#flux-command-form [type=submit]').disabled=true;try{const job=await api('/api/flux/command',{command});fluxSelected=job.id;fluxSubmitting=false;$('#flux-command-status').textContent=job.status==='queued'?'Accepted into the shared byte queue. Waiting for processing.':'Command '+job.status+'.';await refreshFlux();}catch(e){fluxCommandError=true;$('#flux-command-status').textContent=e.message;throw e;}finally{fluxSubmitting=false;$('#flux-command-form [type=submit]').disabled=false;}}
