// A mathematical 4D projection. Motion is derived from received pulse state.
function fluxAnimate(){requestAnimationFrame(fluxAnimate);if(activeView!=='flux'||document.hidden)return;const canvas=$('#flux-canvas'),rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(!rect.width)return;const w=rect.width,h=rect.height;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const angle=reduced?0:(fluxData?.carrier?.pulses||fluxData?.generation||0)*.012;const vertices=[];for(let i=0;i<16;i++){let p=[0,1,2,3].map(b=>(i>>b&1)?1:-1);for(const [a,b,t] of [[0,3,angle],[1,2,angle*.7],[0,1,.3]]){const x=p[a],y=p[b];p[a]=x*Math.cos(t)-y*Math.sin(t);p[b]=x*Math.sin(t)+y*Math.cos(t);}const f=2.8/(3.8-p[3]),pers=3.7/(4.7-p[2]*f),scale=Math.min(w,h)*.24*f*pers;vertices.push([w/2+p[0]*scale,h/2+p[1]*scale,p[3]]);}ctx.save();ctx.translate(w/2,h/2);ctx.strokeStyle='#274c4b';ctx.lineWidth=1;ctx.setLineDash([2,7]);for(let r=1;r<4;r++){ctx.beginPath();ctx.ellipse(0,0,w*.13*r,h*.09*r,-.3,0,Math.PI*2);ctx.stroke();}ctx.restore();ctx.setLineDash([]);const bits=fluxData?.preview?.output_bits||'';for(let i=0;i<16;i++){for(let b=0;b<4;b++){const j=i^(1<<b);if(j<i)continue;ctx.strokeStyle=bits[(i*4+b)%Math.max(1,bits.length)]==='1'?'#90dac5a0':'#789ad575';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(...vertices[i].slice(0,2));ctx.lineTo(...vertices[j].slice(0,2));ctx.stroke();}const [x,y]=vertices[i];ctx.fillStyle=bits[i]==='0'?'#8bb6ed':'#b4f1d3';ctx.beginPath();ctx.arc(x,y,3.6,0,Math.PI*2);ctx.fill();ctx.font='9px Consolas';ctx.fillText(bits[i]||'0',x+7,y-6);}}
requestAnimationFrame(fluxAnimate);

