function bbOptions(el,rows,label){const value=[...el.selectedOptions].map(o=>o.value),markup=rows.map(r=>`<option value="${escapeHTML(r.id)}">${escapeHTML(label(r))}</option>`).join('');if(el.innerHTML!==markup){el.innerHTML=markup;[...el.options].forEach(o=>o.selected=value.includes(o.value));}}
function bbJSON(id,value){fluxText(id,JSON.stringify(value,null,2));}
function bbForm(id,action){$('#'+id).addEventListener('submit',guarded(async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await action(Object.fromEntries(new FormData(e.target)),e);await bbRefresh();}finally{b.disabled=false;}}));}
function bbSelected(form){return [...form.elements.modules.selectedOptions].map(o=>o.value);}
function bbLink(url,label='Source'){return /^https?:\/\//.test(url||'')?`<a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(label)}</a>`:'';}
document.addEventListener('click',guarded(async e=>{const view=e.target.closest('[data-bb-view]');if(view){showView(view.dataset.bbView);await bbRefresh();}const action=e.target.closest('[data-bb-action]');if(action){await api('/api/backbone/'+action.dataset.bbAction,{});await bbRefresh();}const old=e.target.closest('[data-bb-rollback]');if(old){await api('/api/backbone/rollback',{id:old.dataset.bbRollback});await bbRefresh();}const video=e.target.closest('[data-research-url]');if(video){$('#research-run').elements.url.value=video.dataset.researchUrl;$('#research-run').scrollIntoView({behavior:'smooth',block:'center'});}const review=e.target.closest('[data-drill-label]');if(review){await api('/api/drill/feedback',{id:review.dataset.job,module:review.dataset.module,label:Number(review.dataset.drillLabel)});await bbRefresh();}}));
