function bbDraw(canvas,series){const c=$('#'+canvas),w=c.width=900,h=c.height=240,g=c.getContext('2d');g.fillStyle='#0b1720';g.fillRect(0,0,w,h);g.strokeStyle='#253742';for(let y=40;y<h;y+=40){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke();}for(const [values,color,min,max]of series){if(!values?.length)continue;g.strokeStyle=color;g.lineWidth=1.5;g.beginPath();values.forEach((v,i)=>{const x=i/Math.max(1,values.length-1)*w,y=h-(v-min)/(max-min)*h;i?g.lineTo(x,y):g.moveTo(x,y);});g.stroke();}}
function bbDrawSpectrum(){const s=bbSpectrum;if(!s)return;$('#spectrum-summary').textContent=`${s.sample_rate} Hz sampling · ${s.resolution_hz.toFixed(3)} Hz resolution · ${(s.band_power_fraction*100).toFixed(2)}% selected band power · peak ${s.peak.toFixed(4)} · ${(s.near_full_scale_fraction*100).toFixed(2)}% near full scale`;bbDraw('spectrum-wave',[[s.waveform,'#79ddc6',-1,1],[s.isolated_waveform,'#e8bd77',-1,1]]);bbDraw('spectrum-fft',[[s.dbfs,'#79ddc6',-120,6]]);bbJSON('spectrum-receipt',Object.fromEntries(Object.entries(s).filter(([k])=>!['waveform','isolated_waveform','frequencies','dbfs'].includes(k))));}
