function bbRenderDefinitions(){if(!bbDefinitions)return;const q=$('#definition-query').value.toLowerCase();const rows=bbDefinitions.definitions.filter(d=>(d.term+' '+d.definition+' '+d.title).toLowerCase().includes(q));$('#definition-count').textContent=`${rows.length} matching definitions · ${bbDefinitions.definitions.length} total · ${bbDefinitions.automatic?'Automatic research on':'Automatic research paused'}`;function card(d){return `<details class="bb-definition"><summary>${escapeHTML(d.term)} <small>${escapeHTML(d.orientation||'unclassified')}</small></summary><p>${escapeHTML(d.definition)}</p>${d.operational_test?`<p><b>Check:</b> ${escapeHTML(d.operational_test)}</p>`:''}<p class="muted">${escapeHTML(d.title||d.basis||'')} · ${escapeHTML(d.status||'')}</p>${d.evidence?`<blockquote>${escapeHTML(d.evidence)}</blockquote>`:''}${bbLink(d.url)}</details>`;}for(const kind of ['good','evil','other']){const matches=rows.filter(d=>kind==='other'?!['good','evil'].includes(d.orientation):d.orientation===kind);rwReplace('definitions-'+kind,matches.map(card).join('')||'<p class="muted">No matching entries yet.</p>');}}
async function bbRefresh(){if(bbRefreshing||!([...Object.keys(bbPages),'flux','chiral'].includes(activeView)))return;bbRefreshing=true;try{
 if(['backbone','flux','chiral'].includes(activeView)){const s=await api('/api/backbone');$$('.bb-mini-state').forEach(e=>e.textContent=`${s.status} · ${s.evaluations} evaluations · offset ${s.effect.flux_offset} · gain ${s.effect.chiral_gain}`);if(activeView==='backbone'){if(!bbLoaded){const f=$('#bb-config');for(const k of ['goal','provider','interval'])f.elements[k].value=s.config[k];bbOptions(f.elements.modules,s.health,m=>m.id);[...f.elements.modules.options].forEach(o=>o.selected=s.config.modules.includes(o.value));bbLoaded=true;}$('#bb-status').textContent=s.status+(s.error?' · '+s.error:'')+` · next review in ${s.next_review_in}s`;$('#bb-evals').textContent=s.evaluations;$('#bb-offset').textContent=s.effect.flux_offset;$('#bb-gain').textContent=s.effect.chiral_gain;bbJSON('bb-tick',s.last_tick);rwReplace('bb-revisions',s.records.slice().reverse().map(r=>`<details class="bb-definition"><summary>${escapeHTML(r.kind)} · ${escapeHTML(r.status)}${r.active?' · CURRENT':''} · ${escapeHTML(r.time||'')}</summary><p>${escapeHTML(r.reason||r.error||'')}</p><pre class="bb-output">${escapeHTML(r.code||'')}</pre><pre>${escapeHTML(JSON.stringify(r.tests||{},null,2))}</pre>${['active','tested'].includes(r.status)?`<button class="button" data-bb-rollback="${r.id}">Use this tested revision</button>`:''}</details>`).join('')||'<p>No model revisions yet. The initial policy is labelled built-in.</p>');rwReplace('bb-health','<table><thead><tr><th>Module</th><th>Technical status</th><th>Trit / gate</th><th>Unresolved calls</th></tr></thead><tbody>'+s.health.map(m=>`<tr><td>${escapeHTML(m.id)}</td><td>${escapeHTML(m.technical_status)}</td><td>${m.trit??'?'} / ${m.gate??'?'}</td><td>${m.unresolved}</td></tr>`).join('')+'</tbody></table>');}}
