}

function economyDownload(value,filename){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

async function economySave(id,advanced=false){
 const row=economyData.engines.find(r=>r.id===id),card=$('#economy-'+id);
 const inputs={...row.inputs,...(advanced?JSON.parse($('.economy-state',card).value):{}),target:$('.economy-target',card).value,payload:$('.economy-payload',card).value};
 economyData=await api('/api/economy',{engine:id,action:'save',inputs});
}

async function economyPerform(id,action){
 if(economyAction)return;
 const row=economyData?.engines.find(r=>r.id===id);if(!row)return;
 if(action==='source'){await openModule(row.module);return;}
 if(action==='export'){economyDownload(row,row.module+'-results.json');return;}
 economyAction=true;
 try{
  if(['run','start','state'].includes(action))await economySave(id,action==='state');
  if(action!=='state')economyData=await api('/api/economy',{engine:id,action});
  economyRender();
  if(action==='reset'||action==='state'){const state={...economyData.engines.find(r=>r.id===id).inputs};delete state.payload;delete state.target;$('#economy-'+id+' .economy-state').value=JSON.stringify(state,null,2);}
 }finally{economyAction=false;}
}

function economyRender(){
 if(!economyData)return;
 for(const row of economyData.engines){
  let card=$('#economy-'+row.id);if(!card){card=economyCard(row);$('#economy-cards').append(card);}
  $('.economy-status',card).textContent=(row.busy?'Computing':row.running?(economyData.global_running?'Loop active':'Loop waiting · global pause'):'Paused')+' · '+row.cycles+' recorded cycles';
  $('.economy-error',card).textContent=row.error||'';
  for(const key of ['rail_a','rail_b']){const rail=$('[data-rail="'+key+'"]',card);if(!rail.children.length)rail.innerHTML=Array.from({length:8},()=>'<span class="economy-bit">0</span>').join('');row.inputs[key].forEach((bit,i)=>{const cell=rail.children[i];cell.textContent=bit;cell.dataset.bit=bit;});}
  const result=row.last_result,m=result?.metrics||{};
  const pairs=row.id==='banking'?[['Phase',m.phase??row.inputs.phase],['Generated stability',(m.transition_stability??row.inputs.transition_stability).toFixed(1)+'%'],['Generated leverage',(m.elite_leverage??row.inputs.elite_leverage).toFixed(1)+'%'],['Generated abundance',(m.perimeter_abundance??row.inputs.perimeter_abundance).toFixed(1)]]:
    [['Rule state',result?.state||'Ready'],['Generated weight',m.generated_weight??'—'],[row.id==='benefits'?'Generated bps':'Generated outflow',m.generated_bps??m.generated_outflow??'—']];
  $('.economy-metrics',card).innerHTML=pairs.map(([k,v])=>`<div><small>${escapeHTML(k)}</small><strong>${escapeHTML(String(v))}</strong></div>`).join('');
  const output=$('.economy-output',card),next=JSON.stringify(result||{status:'Awaiting first cycle'},null,2);if(output.textContent!==next){const top=output.scrollTop,bottom=output.scrollHeight-output.clientHeight-top<12;output.textContent=next;output.scrollTop=bottom?output.scrollHeight:top;}
  $$('[data-action]',card).forEach(b=>{b.disabled=row.busy&&['run','start','reset','state'].includes(b.dataset.action);});
  const canvas=$('.economy-chart',card),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);
  const values=row.history.map(h=>h.metrics[row.id==='banking'?'perimeter_abundance':row.id==='benefits'?'generated_bps':'generated_outflow']).filter(Number.isFinite).slice(-80);
  ctx.fillStyle='#8ba59e';ctx.font='12px sans-serif';ctx.fillText('Generated '+(row.id==='banking'?'abundance':row.id==='benefits'?'throughput':'outflow')+' · recent cycles',12,17);
  if(values.length){const max=Math.max(...values,1),min=Math.min(...values,0);ctx.strokeStyle='#75e3bd';ctx.lineWidth=2;ctx.beginPath();values.forEach((v,i)=>{const x=12+i/Math.max(1,values.length-1)*(canvas.width-24),y=canvas.height-12-(v-min)/(max-min)*(canvas.height-42);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}
 }
 $('#economy-global').textContent='Loops use the existing worker pool and primary cascade. '+(economyData.global_running?'Automatic scheduling is enabled.':'Global scheduling is paused; Run once remains available.');
 $('#economy-log-path').textContent='Recorded locally: '+economyData.log_path;
 $$('[data-economy-all]').forEach(b=>{b.disabled=b.dataset.economyAll!=='pause'&&economyData.engines.some(r=>r.busy);});
}

async function economyRefresh(){if(economyLoading||economyAction||activeView!=='economy')return;economyLoading=true;try{economyData=await api('/api/economy');economyRender();}finally{economyLoading=false;}}
$$('[data-economy-all]').forEach(b=>b.onclick=async()=>{if(economyAction||!economyData)return;economyAction=true;try{const action=b.dataset.economyAll;if(action!=='pause')for(const row of economyData.engines)await economySave(row.id);economyData=await api('/api/economy',{engine:'all',action});economyRender();}catch(e){toast(e.message);}finally{economyAction=false;}});
$('#economy-export').onclick=()=>{if(economyData)economyDownload(economyData,'economic-engines-results.json');};
setInterval(()=>economyRefresh().catch(e=>toast(e.message)),1200);
if(location.hash==='#economy'){showView('economy');economyRefresh().catch(e=>toast(e.message));}

inference.script:
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let key='', catalog={modules:[],sections:[]},state={},events=[],files=[],active='overview',selected=null,raf=0;
const pages=[['overview','◎','Overview'],['federation','◉','Federated learning'],['automatic','⌁','Automatic inputs'],['loop','↻','Background commands'],['engines','◈','Source engines'],['crypto','⌘','Cryptography'],['ledger','♧','Resource flows'],['bus','⇄','Connections & scripts'],['inference','✳','Local inference'],['archive','▤','Full manuscript'],['receipts','◷','Activity & receipts']];
const symbols=['◇','⌘','◎','⟁','✳','♧','⌁','◈'];
const fmt=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2});
const time=t=>new Date(t*1000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
async function api(path,data){let r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Observatory-Key':key},body:data===undefined?undefined:JSON.stringify(data)});let x=await r.json();if(!r.ok)throw Error(x.error||r.statusText);return x}
function out(el,x){$(el).textContent=JSON.stringify(x,null,2)}
async function work(button,fn){let old=button.textContent;button.disabled=true;button.textContent='Working…';try{await fn()}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent=old}}
function head(eyebrow,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${description}</p></div><div class="actions">${actions}</div></div>`}
function stat(label,value,note){return `<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function panel(title,body,badge=''){return `<section class="panel"><div class="panel-head"><h3>${title}</h3>${badge}</div>${body}</section>`}
function badge(s,type=''){return `<span class="badge ${type}">${esc(s)}</span>`}
function mesh(){return `<div class="mesh"><canvas id="mesh"></canvas><span class="mesh-corner">ACTUAL SOURCE TOPOLOGY / LOCAL REGISTRY</span><div class="mesh-bottom"><div class="mesh-legend"><span><i></i>Core</span><span><i style="background:var(--teal)"></i>Source groups</span></div><span>ORBITS VISUALIZE STRUCTURE</span></div></div>`}
function feed(list=events.slice(0,7)){return `<div class="feed">${list.length?list.map(e=>`<div class="feed-row"><span class="dot"></span><div><b>${esc(e.topic)}</b><small>${esc(JSON.stringify(e.payload).slice(0,115))}</small></div><time>${time(e.ts)}</time></div>`).join(''):'<p class="muted">No receipts yet. Run an operation to create one.</p>'}</div>`}
function engineCard(m,i){let publicMethods=m.methods.filter(x=>!x.name.startsWith('_'));return `<button class="engine" data-engine="${esc(m.id)}"><div class="engine-symbol">${symbols[i%symbols.length]}</div><h3>${esc(m.name.replace(/([a-z])([A-Z])/g,'$1 $2'))}</h3><p>${esc(m.doc||publicMethods[0]?.doc||'Retained source definition with inspectable parameters and executable methods.')}</p><div class="engine-foot"><span>${publicMethods.length} METHODS · LINE ${m.line}</span><b>Open engine ↗</b></div></button>`}
function connections(){let connected=state.bridge?.status==='Connected';return `<div class="connection"><div class="icon-box">◉</div><div><b>Inference Observatory</b><small>HTTP runtime · PID ${state.pid||'—'}</small></div>${badge('LIVE')}</div><div class="connection"><div class="icon-box">⇄</div><div><b>Postscarcity Observatory v4</b><small>Authenticated loopback UDP</small></div>${badge(connected?'ATTACHED':'AWAITING',connected?'':'amber')}</div><div class="connection"><div class="icon-box">⌁</div><div><b>FluxBus v2</b><small>TCP · 127.0.0.1:9999 · send to verify</small></div>${badge('ON DEMAND','blue')}</div>`}
function render(){cancelAnimationFrame(raf);active=location.hash.slice(1)||'overview';if(!pages.some(p=>p[0]===active))active='overview';$('#crumb').textContent=pages.find(p=>p[0]===active)[2].toUpperCase();$('#nav').innerHTML=pages.map(p=>`<a href="#${p[0]}" class="${active===p[0]?'active':''}"><span class="ico">${p[1]}</span>${p[2]}${p[0]==='engines'?`<span class="count">${catalog.modules.length}</span>`:''}</a>`).join('');({overview,federation:federationPage,automatic:automaticPage,loop:loopPage,engines,crypto:cryptoPage,ledger,bus:busPage,inference,archive,receipts}[active])();bindEngineCards();if($('#mesh'))drawMesh()}
function overview(){let groups=new Set(files.map(f=>f.path.split(/[\\/]/)[0])).size;$('#main').innerHTML=head('A LIVING SYSTEMS WORKSPACE','Clarity at the core.','Explore the full manuscript, operate its engines, and follow every result through your local network.',`<button onclick="location.hash='engines'" class="primary">Explore engines ↗</button>`)+`<div class="stats">${stat('Executable definitions',catalog.modules.length,'Retained algorithms · inspectable source')}${stat('Indexed source files',fmt(state.files),'Python + Java · existing apps preserved')}${stat('Recorded events',fmt(state.events),'Durable, timestamped local receipts')}${stat('Bus events received',fmt(state.bridge?.received),'Measured Observatory messages')}</div><div class="grid-main"><div>${panel('Your connected source landscape',mesh(),badge(`${groups} SOURCE GROUPS`,'blue'))}</div><div>${panel('Connection health',`<div class="panel-body">${connections()}<div class="notice">A source file is indexed until it runs or explicitly subscribes. Connection status reflects observed messages.</div><a class="tiny muted" href="#bus">Manage scripts & connections →</a></div>`)}</div></div><div class="two-col">${panel('Observed event activity',`<div class="panel-body"><canvas class="trace" id="trace"></canvas><div class="tiny muted">Persisted event counts / last 12 minutes · no synthetic telemetry</div></div>`,badge('MEASURED','blue'))}${panel('Latest receipts',`<div class="panel-body">${feed(events.slice(0,3))}</div>`,badge('LOCAL'))}</div><div class="section-heading"><h2>Start with a source engine</h2><a class="tiny muted" href="#engines">View all ${catalog.modules.length} →</a></div><div class="cards">${catalog.modules.slice(0,6).map(engineCard).join('')}</div>`;drawTrace()}
function drawTrace(){let c=$('#trace');if(!c)return;let w=c.width=c.clientWidth*2,h=c.height=160,ctx=c.getContext('2d'),counts=Array.from({length:12},(_,i)=>events.filter(e=>e.ts> Date.now()/1000-(12-i)*60&&e.ts<=Date.now()/1000-(11-i)*60).length),max=Math.max(...counts,1);ctx.strokeStyle='#293d41';ctx.beginPath();for(let y=0;y<4;y++){ctx.moveTo(0,y*40+12);ctx.lineTo(w,y*40+12)}ctx.stroke();ctx.strokeStyle='#bce78b';ctx.lineWidth=3;ctx.beginPath();counts.forEach((n,i)=>{let x=i*w/11,y=145-n/max*120;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fillStyle='#a5da7820';ctx.fill()}
function drawMesh(){let canvas=$('#mesh');if(!canvas)return;let ctx=canvas.getContext('2d'),t=0;let names=[...new Set(files.map(f=>f.path.split(/[\\/]/)[0]))].slice(0,18);function frame(){if(!document.body.contains(canvas))return;let w=canvas.width=canvas.clientWidth*devicePixelRatio,h=canvas.height=canvas.clientHeight*devicePixelRatio;ctx.scale(devicePixelRatio,devicePixelRatio);w/=devicePixelRatio;h/=devicePixelRatio;let cx=w/2,cy=h/2;ctx.lineWidth=1;let r=Math.min(w*.34,h*.37);for(let ring of [r*.52,r,r*1.28]){ctx.beginPath();ctx.ellipse(cx,cy,ring,ring*.7,0,0,Math.PI*2);ctx.strokeStyle='#36514c66';ctx.stroke()}names.forEach((name,i)=>{let a=i/names.length*Math.PI*2-.8,x=cx+Math.cos(a)*r*1.2,y=cy+Math.sin(a)*r*.86;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(x,y);ctx.strokeStyle='#5e9b8150';ctx.stroke();let p=((t/170+i*.11)%1);ctx.beginPath();ctx.arc(cx+(x-cx)*p,cy+(y-cy)*p,1.5,0,Math.PI*2);ctx.fillStyle='#bce78b';ctx.fill();ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fillStyle='#59b9b1';ctx.fill();ctx.fillStyle='#859f9f';ctx.font='9px Consolas';ctx.textAlign=x<cx?'right':'left';ctx.fillText(name.length>20?name.slice(0,19)+'…':name,x+(x<cx?-10:10),y+3)});let glow=ctx.createRadialGradient(cx,cy,4,cx,cy,55);glow.addColorStop(0,'#b7e78b44');glow.addColorStop(1,'#b7e78b00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(cx,cy,55,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(cx,cy,28,0,Math.PI*2);ctx.fillStyle='#1c3329';ctx.fill();ctx.strokeStyle='#bce78b';ctx.stroke();ctx.fillStyle='#c5eea3';ctx.font='26px Segoe UI';ctx.textAlign='center';ctx.fillText('✳',cx,cy+8);ctx.font='9px Consolas';ctx.fillStyle='#c0d6c1';ctx.fillText('LOCAL CORE',cx,cy+48);t++;raf=requestAnimationFrame(frame)}frame()}
function engines(){let methods=catalog.modules.reduce((a,m)=>a+m.methods.filter(f=>!f.name.startsWith('_')).length,0);$('#main').innerHTML=head('THE MANUSCRIPT, MADE OPERABLE','Source engine atlas',`${catalog.modules.length} retained definitions. ${methods} public methods. Inspect the code, set parameters and run actual algorithms in bounded Python processes.`)+`<div class="toolbar"><input id="engineSearch" aria-label="Search engines" placeholder="Search cryptography, routing, resource governors, harmonics…"><select id="engineFilter" style="max-width:200px"><option value="">All disciplines</option><option value="Mesh|Node|Router|Constraint|Privilege|Restriction">Mesh & security</option><option value="Ledger|Bank|Credit|Economic|Resource|Floor">Resources & ledger</option><option value="Redemption|Holiday|Christ|Santa|Tree">Restoration</option><option value="Celestial|Harmonic|Quantum|Cognitive|Divine|Shipyard">Research & concepts</option></select></div><div class="notice">Source engines perform real local calculations. Their names and declared interpretations are retained; a software result does not establish a physical, financial or global effect.</div><div class="cards" id="engineCards"></div>`;let update=()=>{let term=$('#engineSearch').value.toLowerCase(),f=$('#engineFilter').value;$('#engineCards').innerHTML=catalog.modules.filter(m=>(m.name+' '+m.doc).toLowerCase().includes(term)&&(!f||new RegExp(f,'i').test(m.name))).map(engineCard).join('');bindEngineCards()};$('#engineSearch').oninput=update;$('#engineFilter').onchange=update;update()}
function bindEngineCards(){document.querySelectorAll('[data-engine]').forEach(b=>b.onclick=()=>openEngine(b.dataset.engine))}
function exampleArg(a){let n=a.name,t=a.type;if(a.default!==null){try{return JSON.parse(a.default.replace(/True/g,'true').replace(/False/g,'false').replace(/None/g,'null'))}catch{}}
if(t==='bytes'||/secret|key$/.test(n))return {$bytes:Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('')};if(/Set/.test(t))return {$set:['local']};if(/List/.test(t))return [];if(/Dict/.test(t)||/payload/.test(n))return {};if(/bool/.test(t))return true;if(/float|int/.test(t)){if(/reserve|pool/.test(n))return 100000;if(/vram/.test(n))return 48;if(/latency/.test(n))return 30;if(/threshold/.test(n))return .2;if(/deception/.test(n))return 0;if(/frequency/.test(n))return 528;if(/utility|intent|capability|capacity/.test(n))return .9;return 10}if(/layer|tier/.test(n))return 'ROOTS';if(/jurisdiction/.test(n))return 'EU';if(/clearance|classification/.test(n))return 'CONFIDENTIAL';if(/node|sender|client|source|entity|sector|shard|target|receiver|worker/.test(n))return 'local-node';return 'local'}
function argsFor(m){return Object.fromEntries((m?.args||[]).map(a=>[a.name,exampleArg(a)]))}
function openEngine(id){selected=catalog.modules.find(m=>m.id===id);let m=selected,init=m.kind==='function'?m.methods[0]:m.methods.find(f=>f.name==='__init__'),pub=m.methods.filter(f=>!f.name.startsWith('_'));$('#detailBody').innerHTML=`<div class="detail-header"><div><h2>${esc(m.name.replace(/([a-z])([A-Z])/g,'$1 $2'))}</h2><p class="sub">${esc(m.doc||'Retained source definition. Add public method calls in the order you want them to execute.')}</p></div>${badge('SOURCE LINE '+m.line,'blue')}</div><div class="engine-diagram"><div class="diagram-node">PARAMETERS<small>Explicit JSON input</small></div><span class="diagram-arrow">→</span><div class="diagram-node">${esc(m.name.length>26?m.name.slice(0,24)+'…':m.name)}<small>Original Python algorithm</small></div><span class="diagram-arrow">→</span><div class="diagram-node">RECEIPT<small>Actual output + elapsed time</small></div></div><div class="two-col"><div><label class="field">Initialization parameters<textarea id="initArgs" class="mono">${esc(JSON.stringify(argsFor(init),null,2))}</textarea></label><div class="tiny muted">Editable example inputs. Byte parameters: {"$bytes":"hex"}; sets: {"$set":[…]}. Each run creates a fresh instance; method calls share it within that run.</div><div class="method-pills">${pub.map(f=>`<button data-addmethod="${esc(f.name)}" title="${esc(f.doc)}">+ ${esc(f.name)}</button>`).join('')}</div><label class="field">Ordered method calls<textarea id="methodCalls" class="mono" style="min-height:165px">[]</textarea></label><button class="primary" id="executeEngine">Run source engine ↗</button><details><summary>Run this plan on a recurring source prompt</summary><label class="field">Exact prompt<select id="bindPrompt">${catalog.sections.map((s,i)=>`<option value="${i}">${i+1}. ${esc(s.title.slice(0,90))}</option>`).join('')}</select></label><button id="bindPlan">Bind current parameters & calls to loop</button><div class="tiny muted">Every cycle executes a fresh instance with this explicit plan. Original errors remain visible.</div></details></div><div><div class="eyebrow">EXECUTION RESULT</div><pre class="output" id="engineResult">Awaiting your inputs. No example has run.</pre><details><summary>Inspect complete retained source</summary><pre>${esc(m.source)}</pre></details><details><summary>Method parameters & documentation</summary><pre>${esc(JSON.stringify(m.methods,null,2))}</pre></details></div></div>`;document.querySelectorAll('[data-addmethod]').forEach(b=>b.onclick=()=>{try{let calls=JSON.parse($('#methodCalls').value),f=pub.find(f=>f.name===b.dataset.addmethod);calls.push({method:f.name,args:argsFor(f)});$('#methodCalls').value=JSON.stringify(calls,null,2)}catch(e){toast(e.message)}});$('#executeEngine').onclick=e=>work(e.target,async()=>{out('#engineResult',await api('run',{id,init:JSON.parse($('#initArgs').value),calls:JSON.parse($('#methodCalls').value)}));refresh()});$('#bindPlan').onclick=e=>work(e.target,async()=>{await api('loop',{prompt_id:+$('#bindPrompt').value,plan:{id,init:JSON.parse($('#initArgs').value),calls:JSON.parse($('#methodCalls').value)}});toast('Source plan bound to recurring prompt')});$('#detail').showModal()}
function cryptoPage(){$('#main').innerHTML=head('REAL CRYPTOGRAPHIC PRIMITIVES','Cryptography laboratory','Authenticated encryption, verifiable identities and deterministic derivation. Operations execute locally; passphrases and plaintext are excluded from activity receipts.')+`<div class="two-col">${panel('Transform a payload',`<div class="panel-body"><label class="field">Operation<select id="cryptoMode"><option value="encrypt">AES-256-GCM · Encrypt</option><option value="decrypt">AES-256-GCM · Decrypt</option><option value="sign">Ed25519 · Sign & verify</option><option value="hash">SHA-256 · Fingerprint</option><option value="derive">PBKDF2 · Derive root key</option><option value="caesar">Caesar cipher · Historical</option><option value="vigenere">Vigenère cipher · Historical</option></select></label><label class="field">Text / encrypted packet<textarea id="cryptoText" placeholder="Your local payload…"></textarea></label><label class="field">Passphrase / Vigenère keyword<input id="cryptoPassword" type="password" autocomplete="off"></label><div class="field-row"><label class="field">Derivation salt (optional hex)<input id="cryptoSalt" placeholder="Random salt generated when empty"></label><label class="field">Caesar shift<input type="number" id="cryptoShift" value="3"></label></div><label class="field"><input type="checkbox" id="classicDecrypt"> Decrypt historical cipher</label><button class="primary" id="cryptoRun">Execute cryptographic operation ↗</button></div>`,badge('LOCAL'))}${panel('Cryptographic result',`<div class="panel-body"><div class="engine-diagram"><div class="diagram-node">INPUT<small>UTF-8 payload</small></div><span class="diagram-arrow">→</span><div class="diagram-node">AUTHENTICATED<small>Standard primitives</small></div></div><pre id="cryptoResult" class="output">No operation performed.</pre><button id="copyCrypto" class="quiet">Copy result</button><div class="notice">AES-GCM uses a fresh 96-bit nonce and 128-bit salt. PBKDF2 uses SHA-256 with 600,000 iterations. Signing generates an ephemeral Ed25519 identity.</div><div class="notice amber">Keep encryption packets and passphrases safely. Root-key derivation displays key material only in this workbench. Historical ciphers are educational.</div></div>`)}</div>`;$('#cryptoRun').onclick=e=>work(e.target,async()=>{let r=await api('crypto',{mode:$('#cryptoMode').value,text:$('#cryptoText').value,password:$('#cryptoPassword').value,salt:$('#cryptoSalt').value,shift:$('#cryptoShift').value,decrypt:$('#classicDecrypt').checked});out('#cryptoResult',r);$('#copyCrypto').onclick=()=>navigator.clipboard.writeText(r.packet||r.output||r.plaintext||JSON.stringify(r)).then(()=>toast('Copied'));refresh()})}
function ledger(){let a=state.accounts||{};$('#main').innerHTML=head('DURABLE LOCAL ACCOUNTING','From canopy to roots.','A transactional resource-unit ledger with signed, expiring, single-use capabilities and a 3.69% commons allocation. These are local accounting units.')+`<div class="stats">${Object.entries(a).map(([n,v])=>stat(n,fmt(v)+' <small>RU</small>',n==='commons'?'Shared reserve · persisted':'Account balance · persisted')).join('')}</div><div class="grid-main">${panel('Authorize & settle',`<div class="panel-body"><div class="field-row"><label class="field">Sender<select id="sender">${['sovereign','canopy','roots'].map(n=>`<option>${n}</option>`).join('')}</select></label><label class="field">Receiver<select id="receiver"><option>roots</option><option>canopy</option><option>sovereign</option></select></label></div><label class="field">Amount (RU)<input id="amount" type="number" min="0.01" step="0.01" value="100"></label><div class="actions"><button id="issueToken">1. Issue capability</button><button id="settle" class="primary">2. Settle transfer ↗</button></div><label class="field" style="margin-top:18px">Capability token<textarea id="token" class="mono" placeholder="Issue a capability for the selected sender"></textarea></label><pre id="ledgerResult">Awaiting authorization.</pre></div>`,badge('ATOMIC'))}${panel('Resource architecture',`<div class="tree-view"><div class="tree-tier">SOVEREIGN CANOPY<small>Capacity & creation</small></div><span class="divider">↓</span><div class="tree-tier">SERVING CANOPY<small>3.69% of outgoing units to commons</small></div><span class="divider">↓</span><div class="tree-tier">ECO-FLOOR ROOTS<small>Shared baseline & restoration</small></div></div><div class="panel-body"><div class="notice">Every transfer conserves total units. Insufficient balances are rejected. Tokens bind the sender and cannot be replayed. No external bank is connected.</div></div>`)}</div>`;$('#issueToken').onclick=e=>work(e.target,async()=>{let r=await api('token',{node:$('#sender').value});$('#token').value=r.token;out('#ledgerResult',{expires:new Date(r.expires*1000).toISOString(),capability:r.capability})});$('#settle').onclick=e=>work(e.target,async()=>{out('#ledgerResult',await api('settle',{sender:$('#sender').value,receiver:$('#receiver').value,amount:$('#amount').value,token:$('#token').value}));await refresh();toast('Settlement committed')})}
function busPage(){$('#main').innerHTML=head('COOPERATIVE LOCAL CONNECTIVITY','Every source has a place.','Index existing Python and Java scripts, run selected entry points, and publish real payloads into your existing application buses.',`<button id="rescan">↻ Rescan sources</button><button id="syncSources" class="primary">Bus all source records ↗</button>`)+`<div class="stats">${stat('Python files',fmt(files.filter(f=>f.language==='py').length),'Source files indexed')}${stat('Java files',fmt(files.filter(f=>f.language==='java').length),'Source files indexed')}${stat('Events sent',fmt(state.bridge?.sent),'UDP · delivery unconfirmed until echoed')}${stat('Echoes observed',fmt(state.bridge?.acknowledged),'Observatory receipt acceptance')}</div><div class="two-col">${panel('Your application connections',`<div class="panel-body">${connections()}<button id="obsSnapshot" class="quiet" style="margin-top:14px">Read actual Observatory snapshot</button><pre id="obsResult" hidden></pre></div>`)}${panel('Publish to the buses',`<div class="panel-body"><label class="field">Payload<textarea id="busText" placeholder="Send explicit text or a compact JSON payload…"></textarea></label><button id="publish" class="primary">Publish & check responses ↗</button><pre id="busResult">Ready. No payload sent.</pre></div>`)}</div><div class="notice">All source files are catalogued without alteration. Run starts the chosen file as its own process with its existing working directory and a 60-second limit. Files do not become subscribed merely by being listed. Cooperative Python and Java bus adapters are included in this app.</div><div class="toolbar"><input id="scriptSearch" placeholder="Search files, definitions or app folders…" aria-label="Search scripts"><select id="language" style="max-width:160px"><option value="">Python + Java</option><option value="py">Python</option><option value="java">Java</option></select></div>${panel('Source registry · real files',`<div class="table-wrap"><table><thead><tr><th>SOURCE / APP</th><th>LANGUAGE</th><th>DEFINITIONS</th><th>BUS ADAPTER</th><th>EXECUTION</th></tr></thead><tbody id="scriptRows"></tbody></table></div>`)}<div class="tiny muted" id="scriptCount"></div>`;let update=()=>{let q=$('#scriptSearch').value.toLowerCase(),lang=$('#language').value;let list=files.filter(f=>(f.path+' '+f.definitions.join(' ')).toLowerCase().includes(q)&&(!lang||f.language===lang));$('#scriptRows').innerHTML=list.slice(0,150).map(f=>{let run=(state.runs||[]).find(r=>r.id===f.id);return `<tr><td class="path">${esc(f.path)}<br><span class="tiny muted">SHA256 ${f.sha256.slice(0,16)}… · ${fmt(f.bytes)} bytes</span></td><td>${f.language==='py'?'Python':'Java'}</td><td>${esc(f.definitions.slice(0,3).join(', ')||'entry point')}</td><td>${badge(f.bus_capable?'PRESENT':'INDEXED',f.bus_capable?'':'blue')}</td><td><button class="quiet" data-run="${f.id}">${run?esc(run.status):'Run file ↗'}</button>${run?`<details><summary>Output</summary><pre>${esc(JSON.stringify(run,null,2))}</pre></details>`:''}</td></tr>`}).join('');$('#scriptCount').textContent=`Showing ${Math.min(list.length,150)} of ${list.length} matching files. Search to narrow the full registry.`;document.querySelectorAll('[data-run]').forEach(b=>b.onclick=e=>work(b,async()=>{let r=await api('script',{id:b.dataset.run});toast('Process '+r.status);await refresh()}))};$('#scriptSearch').oninput=update;$('#language').onchange=update;update();$('#syncSources').onclick=e=>work(e.target,async()=>{out('#busResult',await api('sync',{}));toast('Source metadata synchronization started; delivery results appear in receipts')});$('#rescan').onclick=e=>work(e.target,async()=>{files=(await api('scan',{})).files;update();toast('Registry refreshed')});$('#publish').onclick=e=>work(e.target,async()=>{out('#busResult',await api('publish',{text:$('#busText').value}));refresh()});$('#obsSnapshot').onclick=e=>work(e.target,async()=>{$('#obsResult').hidden=false;out('#obsResult',await api('observatory',{}))})}
