</div></div>`)}</div>${panel('Common subjects across the apps',`<div class="panel-body">${Object.entries(f.subjects).map(([name,count])=>`<div class="connection"><div style="width:150px">${esc(name)}</div><div style="height:7px;background:#24392d;border-radius:8px"><div style="width:${Math.max(2,count/f.apps.length*100)}%;height:7px;background:var(--lime);border-radius:8px"></div></div><span class="tiny muted">${count} apps</span></div>`).join('')}<details><summary>Next research question</summary><pre>${esc(JSON.stringify(f.next_task,null,2))}</pre></details></div>`)}${panel('Research → engine delivery',`<div class="panel-body">${f.research.length?f.research.map(r=>`<details class="panel"><summary class="panel-body"><b>${esc(r.topic)}</b> · ${new Date(r.created*1000).toLocaleString()} · input #${r.input_id}</summary><div class="panel-body"><p class="sub">${esc(r.query)}</p><a href="${esc(r.url)}" target="_blank" rel="noopener" class="tiny muted">Original research source ↗</a><pre>${esc(JSON.stringify(r.delivery,null,2))}</pre></div></details>`).join(''):'<p class="muted">The first captured Google answer will appear here after ingestion. No fabricated research result is shown.</p>'}</div>`)}${panel('All app directories · honest integration status',`<div class="table-wrap"><table><thead><tr><th>APP</th><th>SUBJECTS</th><th>CONNECTION</th><th>LAUNCHERS FOUND</th></tr></thead><tbody>${f.apps.map(a=>`<tr><td><b>${esc(a.name)}</b></td><td class="tiny">${esc(a.subjects.join(', '))}</td><td>${badge(a.connection,a.connection==='adapter_required'?'amber':'blue')}</td><td class="tiny muted">${esc(a.launchers.join(', '))}</td></tr>`).join('')}</tbody></table></div><div class="panel-body tiny muted">Folder discovery does not connect an uninstrumented process. Research is delivered to the resident engines and existing compatible buses; application-level consumption requires each app’s adapter.</div>`)}<button id="refreshFederation">↻ Refresh learning and delivery metrics</button>`;$('#refreshFederation').onclick=()=>federationPage();$('#nativeToggle').onclick=async()=>{await api('research/native',{enabled:!f.native.enabled});federationPage()};$('#nativeInference').onchange=async e=>{await api('research/native',{inference:e.currentTarget.checked});federationPage()};$('#nativeNow').onclick=async()=>{await api('research/native',{run_now:true,enabled:true});federationPage()}}

function nativePanel(n){return panel("Independent research engine",`<div class="panel-body"><div class="stats">${stat("Owner","THIS APP","No chat or browser required")}${stat("Cadence",n.interval/60+" min",n.enabled?"Enabled":"Paused")}${stat("Completed cycles",n.cycles,n.status)}</div><p>Wikipedia evidence → resident engines → compatible buses → neural topic routing.</p><label class="field"><input id="nativeInference" type="checkbox" ${n.inference?"checked":""}> Optional local model synthesis · uses additional RAM</label><p class="tiny muted">Source collection and engine learning continue with this off. Model synthesis is off by default to save memory.</p><p class="tiny muted">Next cycle: ${new Date(n.next_run*1000).toLocaleString()} · ${esc(n.last?.model||"Local model detected each cycle")}</p>${n.error?`<div class="notice amber">${esc(n.error)}</div>`:""}<button id="nativeToggle">${n.enabled?"Pause research":"Resume research"}</button> <button id="nativeNow">Research now</button><details><summary>Latest native receipt</summary><pre>${esc(JSON.stringify(n.last,null,2))}</pre></details><div class="notice">Keep this app and the computer running. Closing Codex or the browser does not stop the detached app. Google AI Mode browser research is a separate feature.</div></div>`,badge(n.running?"RESEARCHING":n.enabled?"AUTONOMOUS":"PAUSED","blue"))}

genesis.script:
const $ = id => document.getElementById(id);
let token, state, filter = 'all', refreshing = false, controller, ticker, selectedProgram, lastProgramOutput = '', toastTimer;
const names = { llama: 'Llama 3', gemini: 'Google Gemini', openai: 'OpenAI' };
async function api(path, data, signal) {
  const response = await fetch(path, { method: data === undefined ? 'GET' : 'POST', headers: { Authorization: `Bearer ${token}`, ...(data === undefined ? {} : { 'Content-Type': 'application/json' }) }, ...(data === undefined ? {} : { body: JSON.stringify(data) }), signal });
  const result = await response.json();
  if (!response.ok && !result.results) throw new Error(result.error || 'The request failed.');
  return result;
}
function toast(message) { $('toast').textContent = message; $('toast').hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(() => $('toast').hidden = true, 3500); }
function showError(message) { $('alert').textContent = message; $('alert').hidden = !message; }
async function refresh() {
  if (refreshing || !token) return;
  refreshing = true;
  try {
    state = await api('/api/status', undefined, AbortSignal.timeout(18000));
    $('node-status').textContent = 'Node active'; $('node-status').className = 'status online';
    $('active-formula').textContent = 'AI GENESIS NODE ACTIVE = TRUE = 1';
    $('llama-state').textContent = state.ollama.ready ? `${state.settings.llamaModel} · Ready` : state.ollama.running ? 'Model not installed' : 'Open Ollama to connect';
    $('llama-state').className = `provider-state ${state.ollama.ready ? 'ready' : ''}`;
    $('gemini-state').textContent = state.settings.geminiConfigured ? 'Key configured' : 'Add API key';
    $('openai-state').textContent = state.settings.openaiConfigured ? 'Key configured' : 'Add API key';
    for (const id of ['gemini', 'openai']) {
      $(`use-${id}`).disabled = !state.settings[`${id}Configured`] || !!controller;
      if (!state.settings[`${id}Configured`]) $(`use-${id}`).checked = false;
    }
    $('last-scan').textContent = new Date(state.checkedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    renderPrograms(); privacy();
  } catch (error) {
    $('node-status').textContent = 'Disconnected'; $('node-status').className = 'status offline';
    $('active-formula').textContent = 'AI GENESIS NODE ACTIVE = FALSE = 0';
    $('llama-state').textContent = 'Status unavailable';
    $('fusion-state').textContent = 'LOCAL CONTROLLER · DISCONNECTED';
    $('process-list').replaceChildren(Object.assign(document.createElement('div'), { className: 'empty-programs', textContent: 'Controller disconnected. Start AI Genesis Node and refresh this page.' }));
  } finally { refreshing = false; }
}
function renderPrograms() {
  const list = $('process-list'); list.replaceChildren();
  const connections = state.connections || [];
  const rows = state.processes.map(p => ({ ...p, bridge: connections.find(c => c.pid === p.pid && c.language === p.language && c.connected) }));
  for (const c of connections.filter(c => c.connected && !rows.some(p => p.pid === c.pid && p.language === c.language))) rows.push({ pid: c.pid, name: c.name, language: c.language, source: c.name, bridge: c });
  rows.sort((a, b) => Number(!!b.bridge) - Number(!!a.bridge) || a.pid - b.pid);
  $('process-count').textContent = rows.length;
  if (state.error) list.append(Object.assign(document.createElement('div'), { className: 'notice', textContent: state.error }));
  const shown = rows.filter(p => filter === 'all' || p.language === filter);
  if (!shown.length) list.append(Object.assign(document.createElement('div'), { className: 'empty-programs', textContent: `No ${filter === 'all' ? 'Python or Java' : filter === 'python' ? 'Python' : 'Java'} programs detected. Start a program to see it here.` }));
  for (const p of shown) {
    const row = document.createElement('button'); row.className = 'process-item';
    const icon = document.createElement('span'); icon.className = `language-badge ${p.language}`; icon.textContent = p.language === 'java' ? 'JV' : 'PY';
    const info = document.createElement('span'); info.className = 'process-info';
    const title = document.createElement('span'); title.className = 'process-name'; title.textContent = p.bridge?.name || p.source || p.name;
    const meta = document.createElement('span'); meta.className = 'process-meta'; meta.textContent = `PID ${p.pid}${p.memoryMB ? ` · ${p.memoryMB} MB` : ''}`;
    const ready = document.createElement('span'); ready.className = `process-meta ${p.bridge ? 'io-ready' : ''}`; ready.textContent = p.bridge ? 'I/O ready' : 'Monitored · connector needed';
    info.append(title, meta, ready); row.append(icon, info); row.onclick = () => p.bridge ? openProgram(p.bridge) : $('guide-dialog').showModal(); list.append(row);
  }
}
function privacy() {
  const mode = $('mode').value;
  const cloud = mode === 'fusion' ? ['gemini', 'openai'].filter(id => $(`use-${id}`).checked).map(id => names[id]) : ['gemini', 'openai'].includes(mode) ? [names[mode]] : [];
  $('privacy-note').textContent = cloud.length ? `Your prompt will also be sent to ${cloud.join(' and ')}. API usage may incur charges.` : 'Your prompt stays on this computer with Llama 3.';
  $('fusion-state').textContent = mode === 'fusion' && cloud.length ? `FUSION · LLAMA 3 + ${cloud.join(' + ').toUpperCase()}` : `${mode === 'fusion' || mode === 'llama' ? 'LLAMA 3' : names[mode].toUpperCase()} · SINGLE MODEL`;
}
async function run() {
  if (controller) return;
  const prompt = $('prompt').value.trim();
  if (!prompt) { $('prompt').focus(); return showError('Enter a prompt to begin.'); }
  showError(''); controller = new AbortController();
  $('generate').hidden = true; $('cancel').hidden = false; $('mode').disabled = true; $('use-gemini').disabled = true; $('use-openai').disabled = true;
  $('output-empty').hidden = true; $('output-content').hidden = true; $('progress').hidden = false; $('perspectives').hidden = true; $('copy-output').disabled = true;
  $('result-label').textContent = 'Working'; $('progress-text').textContent = $('mode').value === 'fusion' ? 'Gathering perspectives, then synthesizing with Llama 3…' : `Waiting for ${names[$('mode').value]}…`;
  const start = Date.now(); $('elapsed').textContent = '0s'; ticker = setInterval(() => $('elapsed').textContent = `${Math.floor((Date.now() - start) / 1000)}s`, 1000);
  try {
    const result = await api('/api/generate', { prompt, mode: $('mode').value, providers: ['llama', ...['gemini', 'openai'].filter(id => $(`use-${id}`).checked)] }, controller.signal);
    $('output').textContent = result.output || result.error;
    $('result-warning').textContent = result.warning || ''; $('result-warning').hidden = !result.warning;
    $('output-content').hidden = false; $('copy-output').disabled = !result.output;
    $('result-label').textContent = !result.ok ? 'Needs attention' : result.synthesized ? 'Synthesized by Llama 3' : 'Individual response';
    $('run-summary').textContent = `${result.results.filter(r => r.ok).length}/${result.results.length} models · ${(result.elapsedMs / 1000).toFixed(1)}s`;
    const list = $('perspective-list'); list.replaceChildren();
    for (const r of result.results) {
      const item = document.createElement('details'), summary = document.createElement('summary'), meta = document.createElement('span'), pre = document.createElement('pre');
      summary.textContent = names[r.id]; meta.textContent = `${r.ok ? 'Answered' : 'Unavailable'} · ${(r.elapsedMs / 1000).toFixed(1)}s`; summary.append(meta); pre.textContent = r.ok ? r.text : r.error; item.append(summary, pre); list.append(item);
    }
    $('perspectives').hidden = false;
    if (!result.ok) showError(result.error);
  } catch (e) {
    const cancelled = e.name === 'AbortError'; $('output').textContent = cancelled ? 'Generation cancelled.' : e.message; $('result-warning').hidden = true; $('output-content').hidden = false; $('result-label').textContent = cancelled ? 'Cancelled' : 'Connection error'; $('run-summary').textContent = cancelled ? 'Cancelled by you' : 'No answer received'; if (!cancelled) showError(e.message);
  } finally {
    clearInterval(ticker); controller = null; $('progress').hidden = true; $('generate').hidden = false; $('cancel').hidden = true; $('mode').disabled = false; refresh();
  }
}
function openSettings() {
  if (state) {
    for (const id of ['llama', 'gemini', 'openai']) $(`${id}-model`).value = state.settings[`${id}Model`];
    $('ollama-detail').textContent = state.ollama.ready ? `Ready · Installed: ${state.ollama.models.join(', ')}` : state.ollama.running ? 'This model is not installed. Run ollama pull llama3, then refresh.' : 'Start Ollama on this computer to enable Llama 3.';
    for (const id of ['gemini', 'openai']) { $(`${id}-key`).value = ''; $(`${id}-key`).placeholder = state.settings[`${id}Configured`] ? 'Configured · leave blank to keep' : `Enter your ${names[id]} API key`; $(`clear-${id}`).checked = false; }
  }
  $('settings-message').textContent = ''; $('settings-dialog').showModal();
}
function openProgram(p) { selectedProgram = p; lastProgramOutput = ''; $('program-title').textContent = p.name; $('program-info').textContent = `${p.language === 'java' ? 'Java' : 'Python'} · PID ${p.pid} · Messages go directly to this program.`; $('program-input').value = ''; $('program-output').textContent = 'Waiting for a message.'; $('use-program-output').disabled = true; $('program-dialog').showModal(); }
$('program-send').onclick = async () => {
  const p = selectedProgram, text = $('program-input').value.trim(); if (!text) return $('program-input').focus();
  $('program-send').disabled = true; $('program-output').textContent = 'Waiting for the program…'; $('use-program-output').disabled = true; lastProgramOutput = '';
  try { const result = await api('/api/program/send', { id: p.id, text }); if (selectedProgram?.id === p.id) { lastProgramOutput = result.output; $('program-output').textContent = result.output || '(Program returned an empty response.)'; $('use-program-output').disabled = !result.output; } }
  catch (e) { $('program-output').textContent = e.message; } finally { $('program-send').disabled = false; }
};
$('use-program-output').onclick = () => { $('prompt').value = `Help me interpret this output from ${selectedProgram.name}:\n\n${lastProgramOutput}`.slice(0, 24000); $('prompt').dispatchEvent(new Event('input')); $('program-dialog').close(); $('prompt').focus(); };
$('settings-form').onsubmit = async e => {
  e.preventDefault(); const button = e.submitter; button.disabled = true;
  try {
    await api('/api/settings', { llamaModel: $('llama-model').value.trim(), geminiModel: $('gemini-model').value.trim(), openaiModel: $('openai-model').value.trim(), geminiKey: $('gemini-key').value.trim(), openaiKey: $('openai-key').value.trim(), clear_geminiKey: $('clear-gemini').checked, clear_openaiKey: $('clear-openai').checked });
    $('gemini-key').value = ''; $('openai-key').value = ''; $('settings-dialog').close(); await refresh(); toast('Connections saved. Select cloud models to include them.');
  } catch (e) { $('settings-message').textContent = e.message; } finally { button.disabled = false; }
};
$('generate').onclick = run; $('cancel').onclick = () => controller?.abort(); $('settings-open').onclick = openSettings; $('guide-open').onclick = () => $('guide-dialog').showModal(); $('refresh').onclick = refresh;
$('prompt').addEventListener('keydown', e => { if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') { e.preventDefault(); run(); } });
$('prompt').addEventListener('input', () => $('char-count').textContent = $('prompt').value.length.toLocaleString());
$('copy-output').onclick = async () => { try { await navigator.clipboard.writeText($('output').textContent); toast('Output copied.'); } catch { toast('Select the output text and copy it manually.'); } };
for (const id of ['mode', 'use-gemini', 'use-openai']) $(id).addEventListener('change', privacy);
document.querySelectorAll('[data-close]').forEach(b => b.onclick = () => $(b.dataset.close).close());
document.querySelectorAll('[data-filter]').forEach(b => b.onclick = () => { filter = b.dataset.filter; document.querySelectorAll('[data-filter]').forEach(x => x.classList.toggle('selected', x === b)); if (state) renderPrograms(); });
document.querySelectorAll('[data-prompt]').forEach(b => b.onclick = () => { $('prompt').value = b.dataset.prompt; $('prompt').dispatchEvent(new Event('input')); $('prompt').focus(); });
try { const response = await fetch('/api/session'); const session = await response.json(); if (!response.ok) throw new Error(session.error); token = session.token; await refresh(); }
catch { showError('Cannot connect to the local controller. Start AI Genesis Node, then refresh.'); }
setInterval(refresh, 5000);

matrix.script:
const $ = id => document.getElementById(id);
const state = { snapshot:null, online:false, session:null, filter:'all', focus:null, paused:matchMedia('(prefers-reduced-motion: reduce)').matches, gain:1.3, job:null, commandPending:false, history:[], historyIndex:0, draft:'', chartCpu:[], chartNetwork:[], chartRuntime:[], lastEvent:0, lastSnapshot:0 };
let toastTimer;
function toast(message) { $('toast').textContent=message; $('toast').hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('toast').hidden=true,4000); }
function bytes(value, rate=false) {
  if (value === null || value === undefined || !Number.isFinite(value)) return '—';
  const units=rate?['B/s','KB/s','MB/s','GB/s']:['B','KB','MB','GB','TB'];
  let n=Math.max(0,value),i=0; while(n>=1024 && i<units.length-1){n/=1024;i++;}
  return `${n.toFixed(i===0?0:n>=100?0:1)} ${units[i]}`;
}
function number(value, digits=1) { return value == null ? '—' : value.toFixed(digits); }
function duration(seconds) { if(seconds==null)return '—';const d=Math.floor(seconds/86400),h=Math.floor(seconds/3600)%24,m=Math.floor(seconds/60)%60;return d?`${d}d ${h}h`:`${h}h ${m}m`; }
function updateSizeStat(prefix,value,isRate) { const [n,u]=bytes(value,isRate).split(' ');$(prefix).textContent=n;$(prefix+'-unit').textContent=u||''; }
function appendConsole(text, kind='') {
  const out=$('console-output'), nearBottom=out.scrollHeight-out.scrollTop-out.clientHeight<45;
  const line=document.createElement('div'); line.className=`console-line ${kind}`;line.textContent=text;out.append(line);
  while(out.children.length>180 || (out.textContent.length>150000 && out.children.length>1))out.firstElementChild.remove();
  if(nearBottom)out.scrollTop=out.scrollHeight;
}
function setOnline(online) {
  state.online=online;
  const el=$('connection');el.className=`connection ${online?'online':'offline'}`;el.replaceChildren(Object.assign(document.createElement('i'),{}),document.createTextNode(online?'SYSTEM LIVE':'SIGNAL OFFLINE'));
  $('telemetry-status').textContent=online?'LIVE':'OFFLINE';
  $('sample-age').textContent=online?'1 s sampling':'Last sample · offline';
  updateStage();
}
function selectedProcesses() {return (state.snapshot?.processes||[]).filter(p=>(state.filter==='all'||p.runtime===state.filter)&&(!state.focus||p.pid===state.focus));}
function updateStage() {
  const rows=selectedProcesses();
  $('stage-state').textContent=state.paused?'VISUALIZATION PAUSED':!state.online?'SIGNAL OFFLINE · AWAITING DATA':rows.length?`${rows.length} SIGNAL${rows.length===1?'':'S'} IN THE STREAM`:'AMBIENT · WAITING FOR RUNTIMES';
  $('rain-empty').hidden=state.online&&rows.length>0;
  const emptyTitle=$('rain-empty').querySelector('strong'),emptyText=$('rain-empty').lastElementChild;
  emptyTitle.textContent=state.online?'Listening for a heartbeat':'Connecting to your machine';
  emptyText.textContent=state.online?`Start a ${state.filter==='all'?'Python or Java':state.filter==='python'?'Python':'Java'} app to bring the matrix to life.`:'Waiting for live process telemetry. Last values may be out of date.';
  const focused=state.snapshot?.processes.find(p=>p.pid===state.focus);
  $('focus-label').hidden=!focused;$('reset-focus').hidden=!focused;
  if(focused)$('focus-label').textContent=`FOCUS / ${focused.label} · ${focused.pid}`;
}
function drawChart(canvas, values, color, ceiling, fill=true, grid=true) {
  const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;
  const ratio=Math.min(devicePixelRatio||1,2),w=rect.width,h=rect.height;
  if(canvas.width!==Math.round(w*ratio)||canvas.height!==Math.round(h*ratio)){canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);}
  const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,w,h);
  if(grid){ctx.strokeStyle='#253627';ctx.lineWidth=.5;for(let y=0;y<3;y++){ctx.beginPath();ctx.moveTo(0,2+y*(h-4)/2);ctx.lineTo(w,2+y*(h-4)/2);ctx.stroke();}}
  const data=values.slice(-60),max=ceiling||Math.max(1024,...data.map(v=>v||0))*1.1;
  if(!data.length)return;
  const points=data.map((v,i)=>({x:(60-data.length+i)/59*w,y:h-3-(Math.max(0,v||0)/max)*(h-6)}));
  ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineWidth=1.4;ctx.strokeStyle=color;ctx.stroke();
  if(fill){ctx.lineTo(points.at(-1).x,h);ctx.lineTo(points[0].x,h);ctx.closePath();const gradient=ctx.createLinearGradient(0,0,0,h);gradient.addColorStop(0,color+'3a');gradient.addColorStop(1,color+'02');ctx.fillStyle=gradient;ctx.fill();}
}
function renderCharts(){drawChart($('system-cpu-chart'),state.chartCpu,'#a5dc8b',100);drawChart($('network-chart'),state.chartNetwork,'#8eb8c5',null,true,false);drawChart($('cpu-spark'),state.chartRuntime,'#a5d884',Math.max(1,...state.chartRuntime.map(v=>v||0))*1.15,false,false);}
const rowsByPid=new Map();
function renderProcesses(processes) {
  const list=$('process-list'),present=new Set(processes.map(p=>p.pid));
  for(const [pid,row] of rowsByPid)if(!present.has(pid)){row.remove();rowsByPid.delete(pid);}
  for(const p of processes){
    let row=rowsByPid.get(p.pid);
    if(!row){row=document.createElement('tr');row.className='process-row';row.tabIndex=0;row.setAttribute('role','button');row.innerHTML='<td><div class="process-name"><span class="runtime-icon"></span><div class="process-details"><strong></strong><small></small></div></div></td><td></td><td></td><td></td><td><span class="signal-bars"><i></i><i></i><i></i><i></i><i></i></span></td>';row.addEventListener('click',()=>setFocus(state.focus===p.pid?null:p.pid));row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();row.click();}});rowsByPid.set(p.pid,row);}
    row.classList.toggle('selected',state.focus===p.pid);row.setAttribute('aria-pressed',String(state.focus===p.pid));row.setAttribute('aria-label',`Focus ${p.label}, PID ${p.pid}`);
    row.title=`${p.label} · PID ${p.pid} · ${p.threads??'Unknown'} threads · Running ${duration(p.ageSeconds)}`;
    const icon=row.querySelector('.runtime-icon');icon.className=`runtime-icon ${p.runtime}`;icon.textContent=p.runtime==='python'?'PY':'JV';
    row.querySelector('strong').textContent=p.label;row.querySelector('small').textContent=`${p.runtime==='python'?'Python':'Java'} / ${p.pid}`;
    row.cells[1].textContent=p.cpu==null?'—':`${number(p.cpu)}%`;row.cells[2].textContent=bytes(p.memoryBytes);row.cells[3].textContent=bytes(p.ioRate,true);
    const bars=row.querySelector('.signal-bars');bars.className=`signal-bars ${p.runtime}`;const strength=Math.min(5,1+Math.ceil((p.cpu||0)*.55+Math.log10(1+(p.ioRate||0))*.25));
    Array.from(bars.children).forEach((bar,i)=>bar.classList.toggle('lit',i<strength));
    // Reorder only when needed, preserving keyboard focus and scroll position.
    const index=processes.indexOf(p);if(list.children[index]!==row)list.insertBefore(row,list.children[index]||null);
  }
  $('process-empty').hidden=processes.length>0;
  $('process-empty').textContent=state.filter==='all'?'No Python or Java processes running. Start an app to connect it.':`No ${state.filter} processes match this filter.`;
  $('process-count').textContent=String(processes.length);
}
function renderSnapshot(snapshot) {
  state.snapshot=snapshot;state.lastSnapshot=Date.now();setOnline(true);
  if(state.focus&&!snapshot.processes.some(p=>p.pid===state.focus)){state.focus=null;toast('Focused process exited. Showing all signals.');}
  const {totals,system}=snapshot;
  $('stat-count').textContent=snapshot.processes.length;
  $('runtime-count').textContent=`${totals.python} PY / ${totals.java} JV`;
  $('stat-cpu').textContent=number(totals.cpu);
  updateSizeStat('stat-memory',totals.memory,false);updateSizeStat('stat-io',totals.io,true);
  $('system-cpu').replaceChildren(document.createTextNode(number(system.cpu)),Object.assign(document.createElement('small'),{textContent:'%'}));
  const percent=system.memoryUsed/system.memoryTotal*100;
  $('system-memory-percent').replaceChildren(document.createTextNode(number(percent,0)),Object.assign(document.createElement('small'),{textContent:'%'}));
  $('memory-bar').style.width=`${percent}%`;$('memory-detail').textContent=`${bytes(system.memoryUsed)} / ${bytes(system.memoryTotal)}`;
  $('network-rx').textContent=bytes(system.networkRx,true);$('network-tx').textContent=bytes(system.networkTx,true);
  $('host').textContent=system.hostname;$('host').title=`${system.platform} · ${system.cpuModel} · ${system.cores} logical cores`;
  $('uptime').textContent=duration(system.uptime);$('system-processes').textContent=system.totalProcesses;
  $('disk-free').textContent=bytes(system.disk?.freeBytes);$('disk-label').textContent=`Disk free${system.disk?' · '+system.disk.name:''}`;
  state.chartCpu.push(system.cpu);state.chartNetwork.push((system.networkRx||0)+(system.networkTx||0));state.chartRuntime.push(totals.cpu);
  for(const values of [state.chartCpu,state.chartNetwork,state.chartRuntime])if(values.length>60)values.shift();
  document.querySelectorAll('.mini-bars i').forEach((el,i)=>{el.style.height=`${5+Math.min(23,Math.log2(1+totals.io)*1.2)*(0.5+(i%3)/4)}px`;el.style.opacity=totals.io>0?'.8':'.25';});
  renderProcesses(snapshot.processes.filter(p=>state.filter==='all'||p.runtime===state.filter));renderCharts();updateStage();
}
function setFocus(pid) {state.focus=pid;renderProcesses((state.snapshot?.processes||[]).filter(p=>state.filter==='all'||p.runtime===state.filter));updateStage();}
function setFilter(filter){state.filter=filter;state.focus=null;document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('selected',el.dataset.filter===filter);el.setAttribute('aria-pressed',String(el.dataset.filter===filter));});renderProcesses((state.snapshot?.processes||[]).filter(p=>filter==='all'||p.runtime===filter));updateStage();}
function setPaused(paused){state.paused=paused;$('pause').setAttribute('aria-label',paused?'Resume rain':'Pause rain');$('pause').title=paused?'Resume rain':'Pause rain';$('pause').innerHTML=paused?'<svg viewBox="0 0 24 24"><path d="m8 5 11 7-11 7z"/></svg>':'<svg viewBox="0 0 24 24"><path d="M8 5v14M16 5v14"/></svg>';updateStage();}
document.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('click',()=>setFilter(el.dataset.filter)));
$('reset-focus').addEventListener('click',()=>setFocus(null));
$('pause').addEventListener('click',()=>setPaused(!state.paused));
$('gain').addEventListener('input',()=>{state.gain=Number($('gain').value);$('gain-value').textContent=state.gain.toFixed(1)+'×';});
async function fullscreen(el){try{if(document.fullscreenElement)await document.exitFullscreen();else await el.requestFullscreen();}catch{toast('Fullscreen is unavailable in this window.');}}
$('fullscreen').addEventListener('click',()=>fullscreen(document.documentElement));$('expand-rain').addEventListener('click',()=>fullscreen($('rain-panel')));
$('help-button').addEventListener('click',()=>$('help-dialog').showModal());$('close-help').addEventListener('click',()=>$('help-dialog').close());$('help-done').addEventListener('click',()=>$('help-dialog').close());
$('clear-console').addEventListener('click',()=>$('console-output').replaceChildren());
document.querySelectorAll('.rail-link[href]').forEach(el=>el.addEventListener('click',()=>{document.querySelectorAll('.rail-link').forEach(x=>x.classList.remove('active'));el.classList.add('active');}));

async function post(endpoint,data){
  if(!state.session)throw new Error('Local command session is not connected.');
  const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','X-Matrix-Token':state.session.token},body:JSON.stringify(data)});
  const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed');return result;
}
function localCommand(command){
  const [name,...args]=command.trim().split(/\s+/);const value=args.join(' ');
  switch(name.toLowerCase()){
    case '/help':appendConsole('/ps                 List connected Python and Java processes\n/focus PID          Isolate one process in the rain\n/focus all          Restore the full stream\n/filter all|python|java\n/gain 0.5–3         Adjust visual sensitivity\n/pause  /resume     Pause or resume the animation\n/clear              Clear the console\n\nOther commands execute in Windows PowerShell. A new shell is created each time.\nFor a long-running app, use Start-Process. Stop cancels the current command tree.','system');return;
    case '/ps':appendConsole((state.snapshot?.processes||[]).map(p=>`${String(p.pid).padEnd(7)} ${p.runtime.padEnd(7)} ${number(p.cpu).padStart(5)}%  ${bytes(p.memoryBytes).padStart(9)}  ${p.label}`).join('\n')||'No matching runtimes are running.','system');return;
    case '/focus':if(value==='all'){setFocus(null);appendConsole('Focus cleared.','system');return;}if(state.snapshot?.processes.some(p=>p.pid===Number(value))){setFilter('all');setFocus(Number(value));appendConsole(`Focused PID ${value}.`,'system');}else appendConsole('That PID is not connected. Use /ps to list processes.','error');return;
    case '/filter':if(['all','python','java'].includes(value)){setFilter(value);appendConsole(`Filter: ${value}`,'system');}else appendConsole('Usage: /filter all|python|java','error');return;
    case '/gain':if(Number(value)>=.5&&Number(value)<=3){$('gain').value=String(Number(value));$('gain').dispatchEvent(new Event('input'));appendConsole(`Sensitivity: ${state.gain}×`,'system');}else appendConsole('Usage: /gain 0.5–3','error');return;
    case '/pause':setPaused(true);appendConsole('Rain paused. Telemetry continues.','system');return;
    case '/resume':setPaused(false);appendConsole('Rain resumed.','system');return;
    case '/clear':$('console-output').replaceChildren();return;
    default:appendConsole('Unknown control. Type /help to see available controls.','error');
  }
}
function commandUI(running){$('cancel-command').hidden=!running;$('run-command').hidden=running;$('run-command').disabled=state.commandPending;$('command-state').textContent=running?'● Command running':state.commandPending?'● Starting…':'● Ready';}
$('command-form').addEventListener('submit',async e=>{
  e.preventDefault();const command=$('command-input').value.trim();if(!command)return;
  if(state.history.at(-1)!==command)state.history.push(command);if(state.history.length>100)state.history.shift();state.historyIndex=state.history.length;state.draft='';
  if(command.startsWith('/')){appendConsole(`❯ ${command}`,'command');$('command-input').value='';localCommand(command);return;}
  if(state.job||state.commandPending){toast('Stop the running command before starting another.');return;}
  state.commandPending=true;commandUI(false);
  try{await post('/api/command',{command});$('command-input').value='';}catch(error){appendConsole(error.message,'error');}
  finally{state.commandPending=false;commandUI(Boolean(state.job));}
});
$('command-input').addEventListener('keydown',e=>{
  if(e.key==='ArrowUp'){e.preventDefault();if(state.historyIndex===state.history.length)state.draft=e.target.value;state.historyIndex=Math.max(0,state.historyIndex-1);e.target.value=state.history[state.historyIndex]||'';}
  if(e.key==='ArrowDown'){e.preventDefault();state.historyIndex=Math.min(state.history.length,state.historyIndex+1);e.target.value=state.historyIndex===state.history.length?state.draft:state.history[state.historyIndex];}
  if(e.key==='Escape')e.target.blur();
});
$('cancel-command').addEventListener('click',async()=>{if(!state.job)return;try{await post('/api/cancel',{id:state.job});}catch(error){appendConsole(error.message,'error');}});
$('shutdown').addEventListener('click',async()=>{try{await post('/api/shutdown',{});events?.close();setOnline(false);setPaused(true);state.session=null;document.body.classList.add('shutdown');$('stage-state').textContent='SESSION ENDED';appendConsole('Matrix Bus stopped. Relaunch with Launch.cmd to reconnect.','system');toast('Matrix Bus stopped. You can close this window.');}catch(error){toast(error.message);}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&document.activeElement.tagName!=='INPUT'&&!$('help-dialog').open){e.preventDefault();$('command-input').focus();}});

// A stream is assigned a process. Every frame interpolates measured activity.
// Ambient streams are deliberately dim and are labeled as ambient in the interface.
const canvas=$('rain'),ctx=canvas.getContext('2d',{alpha:false});
const glyphs='アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン012345789:<>+=*/';
let width=0,height=0,streams=[],lastFrame=0,frameCount=0,lastFps=performance.now(),elapsed=0;
function resizeRain(){const r=canvas.getBoundingClientRect(),ratio=Math.min(devicePixelRatio||1,2);width=r.width;height=r.height;canvas.width=Math.round(width*ratio);canvas.height=Math.round(height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);const count=Math.ceil(width/16);streams=Array.from({length:count},(_,i)=>streams[i]||{y:Math.random()*height*1.7-height*.4,seed:Math.random()*9999,speed:15,energy:0});renderRain(0);renderCharts();}
function renderRain(dt){
  elapsed+=dt;ctx.fillStyle='#030b07';ctx.fillRect(0,0,width,height);ctx.font='12px "Cascadia Code",Consolas,monospace';ctx.textAlign='center';
  const procs=state.online?selectedProcesses():[];const active=procs.length>0;const coreCount=state.snapshot?.system.cores||1;
  // When there are more processes than screen columns, combine their signals
  // into channels so every running process still contributes to the field.
  let channels=procs;
  if(streams.length>0&&procs.length>streams.length){
    channels=streams.map(()=>({cpu:0,ioRate:0,memoryBytes:0,runtimes:[]}));
    procs.forEach((p,i)=>{const channel=channels[i%channels.length];channel.cpu+=p.cpu||0;channel.ioRate+=p.ioRate||0;channel.memoryBytes+=p.memoryBytes||0;channel.runtimes.push(p.runtime);});
    channels.forEach((channel,i)=>{channel.runtime=channel.runtimes[(Math.floor(elapsed/2)+i)%channel.runtimes.length];});
  }
  const globalCpu=procs.reduce((n,p)=>n+(p.cpu||0),0);
  streams.forEach((stream,i)=>{
    const p=active?channels[i%channels.length]:null;
    const cpu=Math.min(2,((p?.cpu||0)*coreCount/100));
    const io=Math.min(1,Math.log2(1+(p?.ioRate||0))/21);
    const mem=Math.min(1,Math.log2(1+(p?.memoryBytes||0)/1048576)/11);
    const speed=active?(24+cpu*135+Math.sqrt(globalCpu)*3+io*45)*state.gain:9;
    stream.speed+=(speed-stream.speed)*Math.min(1,dt*3);stream.energy+=(io-stream.energy)*Math.min(1,dt*4);
    const spacing=17,tail=active?Math.floor(8+mem*23):8;
    stream.y+=dt*stream.speed*(.7+(stream.seed%100)/100);
    if(stream.y-tail*spacing>height+20)stream.y=-Math.random()*170;
    // Staggered gaps and varied trails make the field readable, not a solid wall.
    const presence=active?(i%9===0?.42:1):(i%3===0?1:.15);
    const rgb=p?.runtime==='java'?[225,188,102]:[116,236,145];
    const head=Math.floor(stream.y/spacing);
    for(let j=tail;j>=0;j--){
      const y=stream.y-j*spacing;if(y<12||y>height+15)continue;
      const hash=Math.abs(Math.floor(Math.sin((head-j)*17.32+stream.seed+i*91.7+Math.floor(elapsed*(j===0?9:.9)))*99999));
      const character=glyphs[hash%glyphs.length];const fade=Math.pow(1-j/tail,1.5);
      let alpha=(active?.22+fade*.55:.035+fade*.095)*presence;
      if(j===0&&active){ctx.fillStyle=p.runtime==='java'?`rgba(255,244,187,${.64+stream.energy*.36})`:`rgba(207,255,216,${.64+stream.energy*.36})`;ctx.shadowBlur=stream.energy>0.1?5+stream.energy*8:0;ctx.shadowColor=`rgba(${rgb.join(',')},.8)`;}
      else{alpha=Math.min(.95,alpha+stream.energy*fade*.22);ctx.fillStyle=`rgba(${rgb.join(',')},${alpha})`;ctx.shadowBlur=0;}
      ctx.fillText(character,8+i*16,y);
    }
  });ctx.shadowBlur=0;
}
function animate(now){const dt=Math.min(.05,(now-(lastFrame||now))/1000);lastFrame=now;if(!document.hidden&&!state.paused){renderRain(dt);frameCount++;}if(now-lastFps>1000){$('fps').textContent=state.paused?'PAUSED':`${Math.round(frameCount*1000/(now-lastFps))} FPS`;lastFps=now;frameCount=0;}requestAnimationFrame(animate);}
new ResizeObserver(resizeRain).observe($('rain-stage'));requestAnimationFrame(animate);setPaused(state.paused);
setInterval(()=>{$('clock').textContent=new Date().toLocaleTimeString('en-GB',{hour12:false});if(state.online&&Date.now()-state.lastSnapshot>5000)setOnline(false);},1000);

let events;
async function connect(){
  try{const response=await fetch('/api/session');if(!response.ok)throw new Error('Session unavailable');state.session=await response.json();$('command-input').title=`Working folder: ${state.session.cwd}`;}
  catch{appendConsole('Unable to connect to the local server. Relaunch Matrix Bus.','error');setOnline(false);return;}
  events=new EventSource('/api/events');
  events.addEventListener('session',e=>{const session=JSON.parse(e.data);state.session=session;state.job=session.activeCommand?.id||null;commandUI(Boolean(state.job));});
  events.addEventListener('snapshot',e=>renderSnapshot(JSON.parse(e.data)));
  events.addEventListener('status',e=>{const status=JSON.parse(e.data);setOnline(status.connected);});
  events.addEventListener('activity',e=>{const item=JSON.parse(e.data);if(item.id<=state.lastEvent)return;state.lastEvent=item.id;appendConsole(`[${new Date(item.at).toLocaleTimeString('en-GB',{hour12:false})}] ${item.message}`,'system');});
  events.addEventListener('command',e=>{const message=JSON.parse(e.data);if(message.state==='start'){state.job=message.id;appendConsole(`❯ ${message.command}`,'command');commandUI(true);}if(message.state==='output')appendConsole(message.text,message.type==='stderr'?'error':'');if(message.state==='end'){state.job=null;commandUI(false);appendConsole(`Process exited · code ${message.code??'unknown'}`,message.code===0?'system':'error');}});
  events.onerror=()=>setOnline(false);
}
$('command-input').disabled=true;
connect().finally(()=>{$('command-input').disabled=!state.session;});

carrier.script:
'use strict';
const $=id=>document.getElementById(id),token='integrated';
let state=null,models=[],busy=false,autoSession=null,lastChartKey='',polling=false,apiFailed=false;
const fmt=new Intl.NumberFormat(),reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const num=(x,d=4)=>x===null||x===undefined?'—':Number(x).toFixed(d);
function notice(text){$('notice').textContent=text;$('notice').classList.toggle('show',!!text);}
async function api(path,data){const response=await fetch(path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-Lab-Token':token},body:data===undefined?undefined:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'The request did not complete.');return result;}
function estimate(){const n=Number($('count').value),b=Number($('batch').value);$('estimate').textContent=n>=128&&n<=262144?(Math.ceil(n/b)/7.83).toFixed(2)+' s':'128–262,144 bits';if(!state||state.status==='idle')$('captureCount').textContent='0 / '+fmt.format(n||0)+' bits';}
async function refreshModels(){ $('refresh').disabled=true;try{const previous=$('model').value;const result=await api('/api/models');models=result.models;$('model').replaceChildren();if(!models.length)$('model').append(new Option('No local models installed',''));for(const name of models)$('model').append(new Option(name,name));if(models.includes(previous))$('model').value=previous;$('connection').textContent=models.length?'Ollama connected':'Ollama · no local models';$('connectionDot').classList.toggle('off',!models.length);$('modelHelp').textContent=models.length?'On-device models only. Llama models appear first.':'Install a local Llama model with: ollama pull llama3.2:3b, then refresh.';}catch(error){models=[];$('model').replaceChildren(new Option('Ollama unavailable',''));$('connection').textContent='Ollama offline';$('connectionDot').classList.add('off');$('modelHelp').textContent=error.message;}finally{$('refresh').disabled=false;renderControls();}}
function renderControls(){const running=state?.status==='running',analyzing=state?.analysis.status==='running',hasBits=(state?.stats.n||0)>0;$('start').disabled=busy||running||analyzing;$('start').firstElementChild.textContent=running?'Capturing…':analyzing?'Model is analyzing…':'Generate bits';$('stop').disabled=busy||!running;for(const id of ['count','batch'])$(id).disabled=running||busy||analyzing;$('analyze').disabled=busy||running||analyzing||!hasBits||!$('model').value;$('model').disabled=analyzing;$('exportTxt').disabled=$('exportJson').disabled=running||!hasBits;}
function render(){if(!state)return;const s=state.stats,a=state.analysis,running=state.status==='running';$('nValue').textContent=fmt.format(s.n);$('balanceValue').textContent=s.n?num(s.ones_fraction*100,2):'—';$('entropyValue').textContent=num(s.marginal_entropy,5);$('timeValue').textContent=num(state.elapsed,2);$('cyclesValue').textContent=fmt.format(state.cycles)+' carrier cycles';$('rateValue').textContent=s.n&&state.elapsed>0?fmt.format(Math.round(s.n/state.elapsed))+' bits / second observed':'OS cryptographic source';$('pValue').textContent=s.monobit_p!==null&&s.monobit_p<.0001?s.monobit_p.toExponential(2):num(s.monobit_p,4);$('runsValue').textContent=num(s.runs_z,3);$('correlationValue').textContent=num(s.lag1_correlation,4);$('longestValue').textContent=s.n?s.longest_run+' bits':'—';const progress=100*s.n/state.target;$('progressFill').style.width=progress+'%';$('progress').setAttribute('aria-valuenow',String(Math.round(progress)));$('captureCount').textContent=fmt.format(s.n)+' / '+fmt.format(state.target)+' bits';$('captureStatus').textContent=({idle:'Ready to capture',running:'Capturing · one batch per cycle',complete:'Capture complete',stopped:'Capture stopped · partial data retained',error:'Capture error · '+state.error})[state.status];$('windowLabel').textContent=fmt.format(s.window_size)+'-bit windows';$('byteCount').textContent=fmt.format(Math.floor(s.n/8))+' samples';$('sessionLabel').textContent=state.session_id?'Capture '+state.session_id:'No capture yet';$('report').classList.toggle('empty',a.status==='idle'||a.status==='running');if(a.status==='complete'||a.status==='error'){$('report').textContent=a.text;}else if(a.status==='running'){$('report').textContent='Your local model is examining this capture.\nThe measured statistics and up to 1,024 sample bits are being analyzed on your computer. The first request may take longer while the model loads.';}else{$('report').textContent=s.n?'Capture ready for local interpretation.\nSelect an installed model and choose “Analyze capture” to explain these measurements.':'Your next capture has a story in the numbers.\nGenerate a stream to see what your local model makes of its balance, runs, and adjacent-bit correlation.';}$('reportState').textContent=({idle:s.n?'Statistics ready · interpretation is optional':'Waiting for a capture',running:'Analyzing with '+a.model+' · up to 3 minutes',complete:'Completed with '+a.model+' · '+a.session_id,error:'Analysis unavailable · capture is preserved'})[a.status];renderControls();const key=state.session_id+':'+s.n;if(key!==lastChartKey){drawCharts();lastChartKey=key;}}
async function poll(){if(polling)return;polling=true;try{state=await api('/api/state');if(apiFailed){notice('');apiFailed=false;}render();if(state.status==='complete'&&autoSession===state.session_id){autoSession=null;if($('auto').checked&&$('model').value&&state.analysis.status==='idle')await analyzeCapture();}}catch(error){if(!apiFailed){notice('Dashboard disconnected. Keep the Python engine running, then reload this page. '+error.message);apiFailed=true;}}finally{polling=false;}}
async function action(fn){busy=true;notice('');renderControls();try{await fn();}catch(error){notice(error.message);}finally{busy=false;renderControls();}}
async function analyzeCapture(){try{await api('/api/analyze',{model:$('model').value});state=await api('/api/state');render();}catch(error){notice(error.message);}}
$('start').addEventListener('click',()=>action(async()=>{if(!$('count').reportValidity())return;await api('/api/start',{count:Number($('count').value),batch:Number($('batch').value)});state=await api('/api/state');autoSession=state.session_id;render();}));
$('stop').addEventListener('click',()=>action(async()=>{autoSession=null;await api('/api/stop',{});state=await api('/api/state');render();}));
$('analyze').addEventListener('click',()=>action(analyzeCapture));$('refresh').addEventListener('click',refreshModels);$('model').addEventListener('change',renderControls);$('count').addEventListener('input',estimate);$('batch').addEventListener('change',estimate);
for(const [id,format] of [['exportTxt','txt'],['exportJson','json']])$(id).addEventListener('click',()=>{const a=document.createElement('a');a.href='/api/export?format='+format;a.download='';document.body.append(a);a.click();a.remove();});
function canvas(id){const element=$(id),rect=element.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);const w=Math.max(1,rect.width),h=Math.max(1,rect.height);if(element.width!==Math.round(w*dpr)||element.height!==Math.round(h*dpr)){element.width=Math.round(w*dpr);element.height=Math.round(h*dpr);}const ctx=element.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);return{ctx,w,h};}
function grid(ctx,w,h){ctx.strokeStyle='#273847';ctx.lineWidth=.6;for(let i=0;i<=4;i++){ctx.beginPath();ctx.moveTo(0,10+(h-20)*i/4);ctx.lineTo(w,10+(h-20)*i/4);ctx.stroke();}for(let i=0;i<=8;i++){ctx.beginPath();ctx.moveTo(w*i/8,0);ctx.lineTo(w*i/8,h);ctx.stroke();}}
function empty(ctx,w,h,text){ctx.font='10px Segoe UI, sans-serif';ctx.fillStyle='#71879a';ctx.textAlign='center';ctx.fillText(text,w/2,h/2+4);}
let lastFrame=0;
function waveFrame(ms){if(ms-lastFrame>30){lastFrame=ms;const{ctx,w,h}=canvas('wave');grid(ctx,w,h);const t=reduceMotion?0:ms/1000;const mid=h/2,amp=h*.32;ctx.strokeStyle='#4b6a7b';ctx.setLineDash([3,5]);ctx.beginPath();ctx.moveTo(0,mid);ctx.lineTo(w,mid);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();for(let x=0;x<=w;x+=1){const y=mid-Math.sin(2*Math.PI*7.83*(t-1.5+x/w*1.5))*amp;if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.strokeStyle='#67d7ed';ctx.lineWidth=1.8;ctx.shadowColor='#67d7ed';ctx.shadowBlur=9;ctx.stroke();ctx.shadowBlur=0;const y=mid-Math.sin(2*Math.PI*7.83*t)*amp;ctx.beginPath();ctx.arc(w-2,y,3,0,Math.PI*2);ctx.fillStyle='#bafa75';ctx.fill();ctx.fillStyle='#698497';ctx.font='9px Consolas, monospace';ctx.textAlign='left';ctx.fillText('+1',5,14);ctx.fillText('−1',5,h-5);}requestAnimationFrame(waveFrame);}
function drawCharts(){const s=state?.stats;{const{ctx,w,h}=canvas('field');const bits=state?.preview.slice(-1024)||'';const cell=Math.min(w/32,h/32),ox=(w-cell*32)/2,oy=(h-cell*32)/2;for(let i=0;i<1024;i++){ctx.fillStyle=i<bits.length?(bits[i]==='1'?'#bafa75':'#263e4e'):'#1d2934';ctx.fillRect(ox+(i%32)*cell,oy+Math.floor(i/32)*cell,Math.max(1,cell-1),Math.max(1,cell-1));}if(!bits)empty(ctx,w,h,'Awaiting bits');}
{const{ctx,w,h}=canvas('balance');grid(ctx,w,h);const x0=25,usable=w-x0-3;const y=p=>h-12-p*(h-24);ctx.strokeStyle='#71838e';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(x0,y(.5));ctx.lineTo(w,y(.5));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#748898';ctx.textAlign='left';ctx.font='8px Consolas, monospace';for(const p of [0,.5,1])ctx.fillText(Math.round(p*100)+'%',0,y(p)+3);if(!s?.n)empty(ctx,w,h,'Awaiting a capture');else{for(const [values,color] of [[s.window_balance,'#67d7ed'],[s.cumulative_balance,'#ac9cff']]){ctx.beginPath();values.forEach((p,i)=>{const x=x0+(values.length===1?.5:i/(values.length-1))*usable;i?ctx.lineTo(x,y(p)):ctx.moveTo(x,y(p));});ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.stroke();if(values.length===1){ctx.beginPath();ctx.arc(x0+usable/2,y(values[0]),2.5,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();}}}}
{const{ctx,w,h}=canvas('histogram');grid(ctx,w,h);const hist=s?.byte_histogram||[],max=Math.max(1,...hist),bw=w/256;if(!s?.n)empty(ctx,w,h,'Awaiting complete bytes');else{hist.forEach((v,i)=>{const bh=v/max*(h-16);ctx.fillStyle=i%2?'#8276c5':'#ac9cff';ctx.fillRect(i*bw,h-8-bh,Math.max(.5,bw-.25),bh);});const expected=Math.floor(s.n/8)/256/max*(h-16);ctx.setLineDash([3,4]);ctx.strokeStyle='#67d7ed99';ctx.beginPath();ctx.moveTo(0,h-8-expected);ctx.lineTo(w,h-8-expected);ctx.stroke();ctx.setLineDash([]);}}}
window.addEventListener('resize',()=>{drawCharts();});estimate();drawCharts();requestAnimationFrame(waveFrame);refreshModels();poll();setInterval(()=>{poll();$('binaryPreview').textContent=state?.preview.slice(-512).match(/.{1,64}/g)?.join('\n')||'No bits captured yet.';},400);

ambient.script:
(() => {
  const canvas = document.getElementById('fieldCanvas');
  const ctx = canvas.getContext('2d');
  const badge = document.getElementById('linkBadge');
  const badgeText = document.getElementById('linkBadgeText');
  const statusLine = document.getElementById('sendStatus');
  const statusText = document.getElementById('sendStatusText');
  const eventList = document.getElementById('eventList');
  const payloadInput = document.getElementById('payloadInput');
  const endpointInput = document.getElementById('endpointInput');
  const tunerInput = document.getElementById('tunerInput');
  const sendButton = document.getElementById('sendButton');
  const tunerValue = document.getElementById('tunerValue');
  let metrics = {cpu_percent: 0, rx_rate: 0, tx_rate: 0, memory_percent: 0};
  let fieldTime = 0, lastFrame = performance.now(), size = {width: 0, height: 0};

  function fitCanvas() {
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    size = {width: rect.width, height: rect.height};
    canvas.width = Math.max(1, Math.round(rect.width * dpr));
    canvas.height = Math.max(1, Math.round(rect.height * dpr));
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  new ResizeObserver(fitCanvas).observe(canvas);
  window.addEventListener('resize', fitCanvas);
  fitCanvas();

  function formatBytes(value) {
    if (value === null || value === undefined || !Number.isFinite(Number(value))) return '—';
    const n = Math.max(0, Number(value));
    if (n < 1024) return `${Math.round(n)} B`;
    const units = ['KB', 'MB', 'GB', 'TB'];
    let amount = n / 1024, i = 0;
    while (amount >= 1024 && i < units.length - 1) { amount /= 1024; i++; }
    return `${amount.toFixed(amount >= 100 ? 0 : 1)} ${units[i]}`;
  }
  function formatRate(value) { return `${formatBytes(value)}/s`; }
  function addEvent(tag, message, kind = 'ok') {
    const row = document.createElement('div'); row.className = 'event';
    const time = document.createElement('span'); time.className = 'event-time'; time.textContent = new Date().toLocaleTimeString();
    const label = document.createElement('span'); label.className = `event-tag${kind === 'error' ? ' error' : ''}`; label.textContent = tag;
    const detail = document.createElement('span'); detail.className = 'event-message'; detail.textContent = message;
    row.append(time, label, detail); eventList.prepend(row);
    while (eventList.children.length > 30) eventList.lastElementChild.remove();
  }
  function setSendStatus(message, kind = 'idle') { statusLine.dataset.kind = kind; statusText.textContent = message; }
  function setBadge(text, state = 'idle') { badge.dataset.state = state; badgeText.textContent = text; }

  function updateTelemetry(data) {
    metrics = data;
    document.getElementById('cpuValue').textContent = Number.isFinite(data.cpu_percent) ? `${data.cpu_percent.toFixed(1)}%` : '—';
    document.getElementById('cpuDetail').textContent = `Process ${formatBytes(data.process_rss)} resident`;
    document.getElementById('memoryValue').textContent = Number.isFinite(data.memory_percent) ? `${data.memory_percent.toFixed(1)}%` : '—';
    document.getElementById('memoryDetail').textContent = `${formatBytes(data.memory_used)} of ${formatBytes(data.memory_total)}`;
    document.getElementById('rxValue').textContent = formatRate(data.rx_rate);
    document.getElementById('rxDetail').textContent = `Total ${formatBytes(data.rx_total)}`;
    document.getElementById('txValue').textContent = formatRate(data.tx_rate);
    document.getElementById('txDetail').textContent = `Total ${formatBytes(data.tx_total)}`;
    const names = Array.isArray(data.interface_names) ? data.interface_names.join(', ') : '';
    document.getElementById('hostDetail').textContent = `${data.hostname} · ${data.platform} · ${data.active_interfaces} active interface(s)${names ? ` · ${names}` : ''}`;
    document.getElementById('sampleTime').textContent = `Sampled ${new Date(data.sampled_at).toLocaleTimeString()}`;
    if (!window._firstTelemetry) { window._firstTelemetry = true; addEvent('SYSTEM', 'Live CPU, memory, process, and interface counters are connected.'); }
  }
  window.updateTelemetry = updateTelemetry;

  function setTransmissionResult(result) {
    sendButton.disabled = false; sendButton.textContent = 'Send once';
    if (result.ok) {
      setSendStatus(result.message, 'ok'); setBadge('HTTP RESPONSE RECEIVED', 'ok');
      addEvent('NETWORK', `${result.message} · ${result.sha256}`, 'ok');
    } else {
      setSendStatus(result.message, 'error'); setBadge('REQUEST FAILED', 'error');
      addEvent('NETWORK', result.message, 'error');
    }
  }
  window.setTransmissionResult = setTransmissionResult;

  document.getElementById('previewButton').addEventListener('click', async () => {
    try {
      const result = await window.pywebview.api.preview_payload(payloadInput.value, Number(tunerInput.value));
      if (result.ok) {
        setSendStatus(`Local preview · ${result.bytes} bytes · SHA-256 ${result.sha256}`, 'ok');
        addEvent('PREVIEW', `${result.bytes} UTF-8 bytes · SHA-256 ${result.sha256}`);
      } else {
        setSendStatus(result.message, 'error'); addEvent('PREVIEW', result.message, 'error');
      }
    } catch (err) { setSendStatus(String(err), 'error'); }
  });
  sendButton.addEventListener('click', async () => {
    sendButton.disabled = true; sendButton.textContent = 'Sending…';
    setSendStatus('Preparing one request…'); setBadge('REQUEST IN PROGRESS');
    try {
      const result = await window.pywebview.api.transmit_payload(payloadInput.value, Number(tunerInput.value), endpointInput.value.trim());
      if (!result.ok || result.status !== 'sending') setTransmissionResult(result);
      else { setSendStatus('One request is in progress.'); addEvent('NETWORK', `POST queued to ${result.host} · ${result.sha256}`); }
    } catch (err) { setTransmissionResult({ok: false, message: String(err)}); }
  });
  tunerInput.addEventListener('input', () => { tunerValue.textContent = `${Number(tunerInput.value).toFixed(1)}×`; });

  const particles = Array.from({length: 78}, (_, i) => ({
    angle: Math.random() * Math.PI * 2, radius: .18 + Math.random() * .39,
    drift: .00008 + Math.random() * .00022, phase: Math.random() * Math.PI * 2,
    size: .8 + Math.random() * 1.6, color: i % 4 === 0 ? 'blue' : 'cyan'
  }));
  function draw(now) {
    const dt = Math.min(.05, (now - lastFrame) / 1000); lastFrame = now; fieldTime += dt;
    const w = size.width, h = size.height;
    if (w > 0 && h > 0) {
      ctx.clearRect(0, 0, w, h);
      const cx = w * .5, cy = h * .49, base = Math.min(w, h) * .24;
      const cpu = Math.max(0, Math.min(100, Number(metrics.cpu_percent) || 0));
      const io = Math.log10(1 + Math.max(0, Number(metrics.rx_rate) + Number(metrics.tx_rate)));
      const glow = ctx.createRadialGradient(cx, cy, 5, cx, cy, base * 2.8);
      glow.addColorStop(0, 'rgba(72,196,190,.14)'); glow.addColorStop(.55, 'rgba(56,121,160,.035)'); glow.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = glow; ctx.fillRect(0, 0, w, h);
      for (let ring = 1; ring <= 4; ring++) {
        ctx.beginPath(); ctx.ellipse(cx, cy, base * ring * .65, base * ring * .48, 0, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(116,177,194,${.065 - ring * .008})`; ctx.lineWidth = 1; ctx.stroke();
      }
      const waveHeight = 5 + cpu * .18;
      ctx.beginPath();
      for (let x = 0; x <= w; x += 3) {
        const y = cy + Math.sin(x * .018 - fieldTime * (1 + io * .04)) * waveHeight + Math.sin(x * .006 + fieldTime * .7) * 4;
        if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.strokeStyle = 'rgba(112,225,220,.24)'; ctx.lineWidth = 1; ctx.stroke();
      const positions = particles.map(p => {
        p.angle += p.drift * (1 + io * .08) * (dt * 60);
        return {x: cx + Math.cos(p.angle) * base * (1 + .12 * Math.sin(fieldTime + p.phase)), y: cy + Math.sin(p.angle) * base * .67 * (1 + .12 * Math.cos(fieldTime * .8 + p.phase)), p};
      });
      positions.forEach((a, i) => {
        for (let j = i + 1; j < positions.length; j++) {
          const b = positions[j], dx = a.x - b.x, dy = a.y - b.y, d = Math.hypot(dx, dy);
          if (d < 38) { ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.strokeStyle = `rgba(104,188,205,${(1 - d / 38) * .13})`; ctx.lineWidth = .7; ctx.stroke(); }
        }
      });
      positions.forEach(({x, y, p}) => {
        const color = p.color === 'blue' ? '114,170,255' : '112,225,220';
        ctx.beginPath(); ctx.arc(x, y, p.size + (p.color === 'blue' ? Math.min(1.8, io * .12) : 0), 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${color},${p.color === 'blue' ? .62 : .47})`; ctx.fill();
      });
      const pulseRadius = base * (.18 + ((fieldTime * (.12 + io * .006)) % .76));
      ctx.beginPath(); ctx.arc(cx, cy, pulseRadius, 0, Math.PI * 2);
      ctx.strokeStyle = `rgba(114,170,255,${.32 * (1 - pulseRadius / (base * .95))})`; ctx.lineWidth = 1.2; ctx.stroke();
      const center = ctx.createRadialGradient(cx, cy, 0, cx, cy, 34);
      center.addColorStop(0, 'rgba(112,225,220,.25)'); center.addColorStop(1, 'rgba(112,225,220,0)');
      ctx.fillStyle = center; ctx.beginPath(); ctx.arc(cx, cy, 34, 0, Math.PI * 2); ctx.fill();
      ctx.textAlign = 'center'; ctx.fillStyle = '#d2e8ed'; ctx.font = '600 10px Segoe UI, sans-serif'; ctx.fillText('AMBIENT FIELD', cx, cy - 3);
      ctx.fillStyle = '#7896a8'; ctx.font = '9px Segoe UI, sans-serif'; ctx.fillText(`CPU ${cpu.toFixed(1)}% · I/O ${formatRate(metrics.rx_rate + metrics.tx_rate)}`, cx, cy + 13);
    }
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();


// A separate layer keeps the existing field animation and controls unchanged.
(() => {
  const wrap = document.getElementById('canvasWrap');
  const layer = document.createElement('canvas'); layer.id = 'reactiveCanvas';
  layer.setAttribute('aria-hidden', 'true'); wrap.append(layer);
  const ctx = layer.getContext('2d');
  const readout = document.createElement('div'); readout.className = 'audio-readout';
  readout.dataset.state = 'connecting';
  readout.setAttribute('role', 'img');
  readout.innerHTML = `<div class="audio-readout-head"><span class="audio-readout-label">SYSTEM AUDIO</span><span class="audio-readout-value">Connecting</span></div>
    <svg class="audio-history" viewBox="0 0 190 30" preserveAspectRatio="none" aria-hidden="true"><path class="audio-history-baseline" d="M0 15H190"/><path class="audio-history-fill"/><path class="audio-history-line"/></svg>`;
  wrap.append(readout);
  const value = readout.querySelector('.audio-readout-value');
  const historyLine = readout.querySelector('.audio-history-line');
  const historyFill = readout.querySelector('.audio-history-fill');
  const signalKeys = ['cpu_percent', 'memory_percent', 'rx_rate', 'tx_rate'];
  const cards = [...document.querySelectorAll('.instrument-row .metric')];
  const trails = cards.map((card, i) => {
    const trail = document.createElement('div'); trail.className = 'reactive-trail';
    trail.dataset.signal = signalKeys[i]; trail.setAttribute('aria-hidden', 'true');
    const fill = document.createElement('div'); fill.className = 'reactive-trail-fill';
    trail.append(fill); card.append(trail); return fill;
  });
  const clamp = v => Math.max(0, Math.min(1, Number(v) || 0));
  const levelScale = v => v > .001 ? clamp((20 * Math.log10(v) + 60) / 60) : 0;
  const rateScale = v => clamp(Math.log10(1 + Math.max(0, Number(v) || 0)) / 8);
  const history = Array(64).fill(0);
  let audio = {available: false, peak: 0}, receivedAudio = 0, receivedTelemetry = 0;
  let targets = [0, 0, 0, 0], levels = [0, 0, 0, 0], smoothAudio = 0;
  let width = 0, height = 0, last = performance.now(), activityPhase = 0;
  let historyElapsed = 0, lastStatus = '', lastAriaStatus = '';
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  const originalTelemetry = window.updateTelemetry;
  window.updateTelemetry = data => {
    originalTelemetry(data);
    receivedTelemetry = performance.now();
    targets = [clamp(data.cpu_percent / 100), clamp(data.memory_percent / 100),
      rateScale(data.rx_rate), rateScale(data.tx_rate)];
  };
  window.updateAudio = data => {
    const changedDevice = audio.device_id !== data.device_id;
    audio = {...data, peak: clamp(data.peak)}; receivedAudio = performance.now();
    if (!audio.available || changedDevice) history.fill(0);
  };
  function resize() {
    const bounds = wrap.getBoundingClientRect(), dpr = Math.min(window.devicePixelRatio || 1, 2);
    width = bounds.width; height = bounds.height;
    layer.width = Math.max(1, Math.round(width * dpr)); layer.height = Math.max(1, Math.round(height * dpr));
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  new ResizeObserver(resize).observe(wrap); resize();
  function frame(now) {
    const dt = Math.min(.05, Math.max(0, (now - last) / 1000)); last = now;
    const fresh = receivedAudio > 0 && now - receivedAudio < 1800;
    const available = fresh && audio.available;
    const peak = available ? audio.peak : 0, targetAudio = levelScale(peak);
    smoothAudio += (targetAudio - smoothAudio) * (1 - Math.exp(-dt * (targetAudio > smoothAudio ? 24 : 7)));
    const status = !fresh ? (receivedAudio ? 'Reconnecting' : 'Connecting') :
      !audio.available ? 'Unavailable' : peak < .001 ? 'Quiet' : `${(20 * Math.log10(peak)).toFixed(1)} dBFS`;
    if (status !== lastStatus) { value.textContent = status; lastStatus = status; }
    const state = available ? 'live' : !fresh ? 'connecting' : 'unavailable';
    readout.dataset.state = state;
    readout.title = available ? 'Default playback output · peak level history · before master volume. Audio is not recorded.' :
      audio.message || 'Connecting to the default playback output.';
    // Accessibility descriptions change with connection state, not every audio sample.
    const ariaStatus = `System audio: ${state}. ${readout.title}`;
    if (ariaStatus !== lastAriaStatus) { readout.setAttribute('aria-label', ariaStatus); lastAriaStatus = ariaStatus; }
    if (!fresh) history.fill(0);
    historyElapsed += dt;
    if (historyElapsed >= .05) {
      historyElapsed %= .05; history.shift(); history.push(targetAudio);
      if (!reducedMotion.matches) {
        const upper = history.map((v, i) => `${(i * 190 / 63).toFixed(1)},${(15 - v * 13).toFixed(1)}`);
        const lower = history.map((v, i) => `${(i * 190 / 63).toFixed(1)},${(15 + v * 13).toFixed(1)}`).reverse();
        historyLine.setAttribute('d', `M${upper.join(' L')}`);
        historyFill.setAttribute('d', `M${upper.join(' L')} L${lower.join(' L')} Z`);
      } else { historyLine.setAttribute('d', ''); historyFill.setAttribute('d', ''); }
    }
    const telemetryFresh = receivedTelemetry > 0 && now - receivedTelemetry < 3500;
    levels = levels.map((v, i) => v + ((telemetryFresh ? targets[i] : 0) - v) * (1 - Math.exp(-dt * 5)));
    trails.forEach((trail, i) => {
      trail.style.transform = `scaleX(${reducedMotion.matches ? (telemetryFresh ? targets[i] : 0) : levels[i]})`;
    });
    ctx.clearRect(0, 0, width, height);
    if (!reducedMotion.matches && width > 0 && height > 0) {
      const cx = width * .5, cy = height * .49, base = Math.min(width, height) * .24;
      activityPhase += dt * (.12 + levels[0] * .55 + (levels[2] + levels[3]) * .35);
      // A breathing halo follows the measured output amplitude; silence has no halo.
      if (smoothAudio > .003) {
        for (let ring = 0; ring < 2; ring++) {
          ctx.beginPath(); ctx.ellipse(cx, cy, base * (1.24 + ring * .13 + smoothAudio * .13),
            base * (.86 + ring * .1 + smoothAudio * .09), 0, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(112,225,220,${smoothAudio * (ring ? .12 : .34)})`;
          ctx.lineWidth = 1 + smoothAudio * .7; ctx.stroke();
        }
      }
      // Short orbital traces follow CPU/memory load and actual inbound/outbound traffic.
      levels.forEach((level, i) => {
        if (level < .003) return;
        const angle = activityPhase * (i % 2 ? -1 : 1) + i * Math.PI / 2;
        const rx = base * (1.58 + i * .16), ry = rx * .72;
        ctx.beginPath(); ctx.ellipse(cx, cy, rx, ry, 0, angle, angle + .08 + level * .72);
        ctx.strokeStyle = `rgba(${i < 2 ? '112,225,220' : '114,170,255'},${.06 + level * .26})`;
        ctx.lineWidth = 1; ctx.stroke();
        const end = angle + .08 + level * .72;
        ctx.beginPath(); ctx.arc(cx + Math.cos(end) * rx, cy + Math.sin(end) * ry, 1 + level, 0, Math.PI * 2);
        ctx.fillStyle = ctx.strokeStyle; ctx.fill();
      });
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();

injector.script:
'use strict';
const $ = id => document.getElementById(id);
const canvas = $('fluxCanvas'), ctx = canvas.getContext('2d');
const terminal = $('assemblyTerminal'), intentIn = $('intentInput'), orderIn = $('orderInput');
const encoder = new TextEncoder();
const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
let paused = reducedMotion.matches, bridgeReady = false, busy = false;
let latest = null, lastReceived = 0, lastEvent = 0, lastRevision = -1;
let history = [], smoothedCPU = 0, smoothedCores = [], phase = 0, writeFlash = 0;
let viewWidth = 0, viewHeight = 0, lastFrame = 0, staleState = '';
const providerIds = ['llama','gemini','openai'];
let networkVersion = -1, networkBusy = false, networkHydrated = false;
let networkRequestPending = false, networkRunning = false;

function networkFeedback(message,error=false) { $('networkFeedback').textContent=message; $('networkFeedback').classList.toggle('error',error); }
function lockNetwork(locked) {
  networkBusy=locked || networkRequestPending;
  $('runNetworkButton').disabled=!bridgeReady || networkBusy;
  $('forgetKeysButton').disabled=!bridgeReady || networkBusy;
  $('networkTokens').disabled=networkBusy;
  for(const id of providerIds) {$(id+'Settings').disabled=networkBusy;$(id+'Enabled').disabled=networkBusy;}
}
function applyNetwork(data) {
  if(!data || data.version <= networkVersion) return;
  networkVersion=data.version;
  if(!networkHydrated) {
    for(const id of providerIds) {$(id+'Model').value=data.providers[id].model;$(id+'Enabled').checked=data.providers[id].enabled;}
    $('llamaEndpoint').value=data.providers.llama.endpoint;networkHydrated=true;
  }
  $('networkFlag').textContent=(data.running?'RUNNING / ':'LAST RUN / ')+'ACTIVE = '+(data.active?'TRUE':'FALSE');
  networkRunning=data.running;lockNetwork(networkRunning);
  for(const id of providerIds) {
    const provider=data.providers[id],status=$(id+'Status');
    status.textContent=provider.status.replaceAll('_',' ').toUpperCase();status.className='provider-status '+provider.status;
    if(provider.output || provider.error) $(id+'Output').textContent=provider.output || provider.error;
    else $(id+'Output').textContent=provider.status==='running'?'Waiting for the provider reply…':'Awaiting a request.';
    $(id+'Meta').textContent=provider.latency_ms!==null?`${(provider.latency_ms/1000).toFixed(2)} s · ${provider.model}`:`${provider.model} · ${provider.status.replaceAll('_',' ')}`;
    if(id!=='llama') $(id+'KeyHint').textContent=provider.key_configured?'Key configured for this session. Leave blank to keep it.':`Enter an API key, or set ${id==='openai'?'OPENAI_API_KEY':'GEMINI_API_KEY'} before launch.`;
  }
  if(!data.running && data.run_id>0) {
    const succeeded=providerIds.filter(id=>data.providers[id].status==='active').length;
    networkFeedback(`${succeeded} of ${data.selected_count} selected providers returned complete replies.`,succeeded<data.selected_count);
  }
}
$('runNetworkButton').addEventListener('click',async()=>{
  if(!bridgeReady || networkBusy) return;
  if(!intentIn.value.trim()) {networkFeedback('Enter an intent above before running inference.',true);intentIn.focus();return;}
  const tokens=Number($('networkTokens').value);
  if(!Number.isInteger(tokens)||tokens<128||tokens>8192) {networkFeedback('Choose an output limit from 128 to 8,192 tokens.',true);return;}
  const settings={};
  for(const id of providerIds) settings[id]={enabled:$(id+'Enabled').checked,model:$(id+'Model').value,api_key:id==='llama'?'':$(id+'Key').value};
  settings.llama.endpoint=$('llamaEndpoint').value;
  networkRequestPending=true;lockNetwork(true);networkFeedback('Dispatching the current intent to the selected providers…');
  try {
    const result=await window.pywebview.api.run_inference_network(intentIn.value,settings,tokens);
    applyNetwork(result.network);
    networkFeedback(result.message,!result.ok);
    if(result.ok) { $('geminiKey').value='';$('openaiKey').value=''; }
  } catch(error) {networkFeedback('The local engine could not start the inference request.',true);}
  finally {networkRequestPending=false;lockNetwork(networkRunning);}
});
$('forgetKeysButton').addEventListener('click',async()=>{
  if(!bridgeReady || networkBusy) return;networkRequestPending=true;lockNetwork(true);
  try {const result=await window.pywebview.api.forget_inference_keys();applyNetwork(result.network);$('geminiKey').value='';$('openaiKey').value='';networkFeedback(result.message,!result.ok);}
  catch(error) {networkFeedback('The local engine did not confirm key removal.',true);}
  finally {networkRequestPending=false;lockNetwork(networkRunning);}
});

function appendLog(kind, message, timestamp, error=false) {
  const atBottom = terminal.scrollHeight - terminal.scrollTop - terminal.clientHeight < 28;
  const row = document.createElement('div'); row.className = 'log-line' + (error ? ' error' : '');
  const clock = document.createElement('span'); clock.className = 'log-time';
