const p=probeResult?.probe||state.probe;$('probeReadout').textContent='PROBE '+signed(p.x)+', '+signed(p.y);$('probability').textContent='P(MINT) '+(p.probability*100).toFixed(1)+'%';}
function signed(x){return (x>=0?'+':'')+x.toFixed(2)}
