ctx.lineWidth=.5;ctx.strokeStyle='rgba(223,234,249,.12)';for(let i=0;i<=4;i++){ctx.beginPath();ctx.moveTo(b.x+i*b.size/4,b.y);ctx.lineTo(b.x+i*b.size/4,b.y+b.size);ctx.stroke();ctx.beginPath();ctx.moveTo(b.x,b.y+i*b.size/4);ctx.lineTo(b.x+b.size,b.y+i*b.size/4);ctx.stroke()}
// Marching squares draws the actual p=0.5 boundary, not a decorative curve.
